const LOG_PATH = "/tmp/…/app.log";

function main(): void {
  const fs = require("fs");
  const text = fs.readFileSync(LOG_PATH, "utf8");

  const entries = [];
  const linePattern = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] ([A-Za-z0-9_]+) \((.*)\) - (.*)$/;

  const rawLines = text.split(/\r\n|\r|\n/);
  for (let i = 0; i < rawLines.length; i++) {
    const line = rawLines[i].trim();
    if (line === "") {
      continue;
    }

    const match = linePattern.exec(line);
    if (!match) {
      continue;
    }

    const dateTime = match[1];
    const level = match[2];
    const component = match[3];
    const message = match[4];
    const hour = dateTime.slice(11, 13);

    entries.push({
      dateTime: dateTime,
      level: level,
      component: component,
      message: message,
      hour: hour
    });
  }

  function countsByKey(arr: any[], key: string): Array<{ key: string; count: number }> {
    const map: any = {};

    for (let i = 0; i < arr.length; i++) {
      const k = arr[i][key];
      if (!map[k]) {
        map[k] = 0;
      }
      map[k] += 1;
    }

    const result = [];
    for (const k in map) {
      if (Object.prototype.hasOwnProperty.call(map, k)) {
        result.push({ key: k, count: map[k] });
      }
    }

    result.sort(function (a: any, b: any) {
      return a.key < b.key ? -1 : (a.key > b.key ? 1 : 0);
    });

    return result;
  }

  function maxCount(counts: Array<{ key: string; count: number }>, emptyKey: string, emptyCount: number): { key: string; count: number } {
    if (counts.length === 0) {
      return { key: emptyKey, count: emptyCount };
    }

    let best = counts[0];
    for (let i = 1; i < counts.length; i++) {
      if (counts[i].count > best.count) {
        best = counts[i];
      }
    }

    return best;
  }

  const levelCounts = countsByKey(entries, "level");

  const errorEntries = [];
  for (let i = 0; i < entries.length; i++) {
    if (entries[i].level === "ERROR") {
      errorEntries.push(entries[i]);
    }
  }

  const errorComponentCounts = countsByKey(errorEntries, "component");
  const topErrorComponent = maxCount(errorComponentCounts, "None", 0);

  const uniqueMessages = [];
  for (let i = 0; i < errorEntries.length; i++) {
    const msg = errorEntries[i].message;
    if (uniqueMessages.indexOf(msg) === -1) {
      uniqueMessages.push(msg);
    }
  }

  uniqueMessages.sort(function (a: string, b: string) {
    return a < b ? -1 : (a > b ? 1 : 0);
  });

  const hourCounts = countsByKey(entries, "hour");
  const topHour = maxCount(hourCounts, "00", 0);

  const outputLines = [];

  outputLines.push("=== Log Analysis ===");
  outputLines.push("");
  outputLines.push("Entries by Level:");

  for (let i = 0; i < levelCounts.length; i++) {
    outputLines.push("  " + levelCounts[i].key + ": " + levelCounts[i].count);
  }

  outputLines.push("");
  outputLines.push("Component with Most Errors: " + topErrorComponent.key + " (" + topErrorComponent.count + " errors)");

  outputLines.push("");
  outputLines.push("Unique Error Messages:");

  for (let i = 0; i < uniqueMessages.length; i++) {
    outputLines.push("  - " + uniqueMessages[i]);
  }

  outputLines.push("");
  outputLines.push("Busiest Hour: " + topHour.key + ":00 (" + topHour.count + " entries)");

  process.stdout.write(outputLines.join("\n") + "\n");
}

main();

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    private static final String LOG_FILE =
        "/tmp/…/app.log";

    private static final Pattern LINE_PATTERN = Pattern.compile(
        "^\\s*\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\]\\s+(\\S+)\\s+\\(([^)]*)\\)\\s*-\\s*(.*)$"
    );

    public static void main(String[] args) {
        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorCountsByComponent = new HashMap<>();
        Set<String> uniqueErrorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        try (BufferedReader reader = Files.newBufferedReader(Paths.get(LOG_FILE), StandardCharsets.UTF_8)) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("﻿")) {
                    line = line.substring(1);
                }

                Matcher matcher = LINE_PATTERN.matcher(line);
                if (!matcher.matches()) {
                    continue;
                }

                String timestamp = matcher.group(1);
                String level = matcher.group(2);
                String component = matcher.group(3);
                String message = matcher.group(4).trim();

                levelCounts.merge(level, 1, Integer::sum);

                String hour = timestamp.substring(11, 13) + ":00";
                hourCounts.merge(hour, 1, Integer::sum);

                if (level.equalsIgnoreCase("ERROR")) {
                    errorCountsByComponent.merge(component, 1, Integer::sum);
                    uniqueErrorMessages.add(message);
                }
            }
        } catch (IOException e) {
            // If the file cannot be read, produce an empty analysis rather than failing.
        }

        StringBuilder output = new StringBuilder();

        output.append("=== Log Analysis ===\n\n");
        output.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            output.append("  ").append(entry.getKey()).append(": ").append(entry.getValue()).append('\n');
        }
        output.append('\n');

        String componentWithMostErrors = "None";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : errorCountsByComponent.entrySet()) {
            int count = entry.getValue();
            if (count > maxErrors ||
                (count == maxErrors && entry.getKey().compareTo(componentWithMostErrors) < 0)) {
                componentWithMostErrors = entry.getKey();
                maxErrors = count;
            }
        }

        output.append("Component with Most Errors: ").append(componentWithMostErrors)
              .append(" (").append(maxErrors).append(" errors)\n\n");

        output.append("Unique Error Messages:\n");
        for (String message : uniqueErrorMessages) {
            output.append("  - ").append(message).append('\n');
        }
        output.append('\n');

        String busiestHour = "00:00";
        int maxEntries = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            int count = entry.getValue();
            if (count > maxEntries ||
                (count == maxEntries && entry.getKey().compareTo(busiestHour) < 0)) {
                busiestHour = entry.getKey();
                maxEntries = count;
            }
        }

        output.append("Busiest Hour: ").append(busiestHour)
              .append(" (").append(maxEntries).append(" entries)\n");

        System.out.print(output.toString());
    }
}

