declare const require: (moduleName: string) => any;
declare const process: any;

function isPlainObject(value: any): boolean {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function setOwnProperty(target: any, key: string, value: any): void {
  Object.defineProperty(target, key, {
    value: value,
    enumerable: true,
    configurable: true,
    writable: true
  });
}

function canonical(value: any): string {
  if (Array.isArray(value)) {
    let result = '[';
    for (let i = 0; i < value.length; i++) {
      if (i > 0) result += ',';
      result += canonical(value[i]);
    }
    return result + ']';
  }

  if (isPlainObject(value)) {
    const keys = Object.keys(value).sort();
    let result = '{';
    for (let i = 0; i < keys.length; i++) {
      if (i > 0) result += ',';
      result += JSON.stringify(keys[i]) + ':' + canonical(value[keys[i]]);
    }
    return result + '}';
  }

  if (value === undefined) {
    return 'undefined';
  }

  return JSON.stringify(value);
}

function mergeValues(a: any, b: any): any {
  if (Array.isArray(a) && Array.isArray(b)) {
    const seen: string[] = [];
    const result: any[] = [];

    for (let i = 0; i < a.length; i++) {
      const key = canonical(a[i]);
      if (seen.indexOf(key) === -1) {
        seen.push(key);
        result.push(a[i]);
      }
    }

    for (let i = 0; i < b.length; i++) {
      const key = canonical(b[i]);
      if (seen.indexOf(key) === -1) {
        seen.push(key);
        result.push(b[i]);
      }
    }

    return result;
  }

  if (isPlainObject(a) && isPlainObject(b)) {
    const keys: string[] = Object.keys(a).concat(Object.keys(b));
    const uniqueKeys: string[] = [];

    for (let i = 0; i < keys.length; i++) {
      if (uniqueKeys.indexOf(keys[i]) === -1) {
        uniqueKeys.push(keys[i]);
      }
    }

    const result: any = {};

    for (let i = 0; i < uniqueKeys.length; i++) {
      const key = uniqueKeys[i];
      const hasA = Object.prototype.hasOwnProperty.call(a, key);
      const hasB = Object.prototype.hasOwnProperty.call(b, key);

      if (hasA && hasB) {
        setOwnProperty(result, key, mergeValues(a[key], b[key]));
      } else if (hasA) {
        setOwnProperty(result, key, a[key]);
      } else {
        setOwnProperty(result, key, b[key]);
      }
    }

    return result;
  }

  return b;
}

function sortKeysDeep(value: any): any {
  if (Array.isArray(value)) {
    const result: any[] = [];
    for (let i = 0; i < value.length; i++) {
      result.push(sortKeysDeep(value[i]));
    }
    return result;
  }

  if (isPlainObject(value)) {
    const result: any = {};
    const keys = Object.keys(value).sort();
    for (let i = 0; i < keys.length; i++) {
      setOwnProperty(result, keys[i], sortKeysDeep(value[keys[i]]));
    }
    return result;
  }

  return value;
}

function readJson(filename: string): any {
  return JSON.parse(require('fs').readFileSync(filename, 'utf8'));
}

function main(): void {
