import Foundation

let logPath = "/tmp/…/app.log"

struct LogEntry {
    let timestamp: String
    let level: String
    let component: String
    let message: String
}

func parseLine(_ line: String) -> LogEntry? {
    guard line.hasPrefix("[") else { return nil }
    guard let close = line.index(of: "]") else { return nil }

    let timestamp = String(line[line.index(after: line.startIndex)...close])

    var rest = line[close + 1...]
    rest = rest.drop(where: { $0 == " " || $0 == "\t" })

    guard let levelEnd = rest.firstIndex(where: { $0 == " " || $0 == "\t" }) else { return nil }
    let level = String(rest[..<levelEnd])

    let afterLevel = rest[levelEnd + 1...]
    afterLevel = afterLevel.drop(where: { $0 == " " || $0 == "\t" })

    guard let componentEnd = afterLevel.firstIndex(where: { $0 == ")" }) else { return nil }
    let component = String(afterLevel[..<componentEnd].dropFirst())

    let afterComponent = afterLevel[componentEnd + 1...]
    afterComponent = afterComponent.drop(where: { $0 == " " || $0 == "\t" })

    guard afterComponent.hasPrefix("-") else { return nil }
    let message = String(afterComponent.dropFirst().drop(where: { $0 == " " || $0 == "\t" }))

    guard timestamp.count >= 13 else { return nil }

    return LogEntry(timestamp: timestamp, level: level, component: component, message: message)
}

var entries: [LogEntry] = []

do {
    let content = try String(contentsOfFile: logPath, encoding: .utf8)
    for rawLine in content.split(separator: "\n", omittingEmptySubstrings: true) {
        let line = String(rawLine).trimmingCharacters(from: .whitespacesAndNewlines)
        if let entry = parseLine(line) {
            entries.append(entry)
        }
    }
} catch {
    // If the file cannot be read, continue with an empty analysis.
}

let levelCounts: [String: Int] = entries.reduce(into: [String: Int]()) {
    $0[$1.level, default: 0] += 1
}

let errorEntries = entries.filter { $0.level.uppercased() == "ERROR" }

let componentErrorCounts: [String: Int] = errorEntries.reduce(into: [String: Int]()) {
    $0[$1.component, default: 0] += 1
}

let uniqueErrorMessages = Set(errorEntries.map { $0.message }).sorted()

var hourCounts: [String: Int] = [:]
for entry in entries {
    let hourText = String(entry.timestamp[11..<13])
    let hour = hourText.count == 1 ? "0\(hourText)" : hourText
    hourCounts[hour, default: 0] += 1
}

func best(_ counts: [String: Int]) -> (String, Int)? {
    guard !counts.isEmpty else { return nil }
    return counts.keys.sorted {
        let left = counts[$0]!
        let right = counts[$1]!
        if left != right { return left > right }
        return $0 < $1
    }.first!
}

let busiestHour = best(hourCounts)
let mostErrorComponent = best(componentErrorCounts)

let componentName = mostErrorComponent?.$0 ?? ""
let componentErrorCount = mostErrorComponent?.$1 ?? 0
let busiestHourName = busiestHour?.$0 ?? "00"
let busiestHourCount = busiestHour?.$1 ?? 0

print("=== Log Analysis ===")
print()
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print()
print("Component with Most Errors: \(componentName) (\(componentErrorCount) errors)")
print()
print("Unique Error Messages:")
for message in uniqueErrorMessages {
    print("  - \(message)")
}
print()
print("Busiest Hour: \(busiestHourName) (\(busiestHourCount) entries)")

