    // If the file cannot be read, continue with an empty analysis.
}

let levelCounts: [String: Int] = entries.reduce(into: [String: Int]()) {
    $0[$1.level, default: 0] += 1
}

let errorEntries = entries.filter { $0.level.uppercased() == "ERROR" }

let componentErrorCounts: [String: Int] = errorEntries.reduce(into: [String: Int]()) {
    $0[$1.component, default: 0] += 1
}

let uniqueErrorMessages = Set(errorEntries.map { $0.message }).sorted()

var hourCounts: [String: Int] = [:]
for entry in entries {
    let hourText = String(entry.timestamp[11..<13])
    let hour = hourText.count == 1 ? "0\(hourText)" : hourText
    hourCounts[hour, default: 0] += 1
}

func best(_ counts: [String: Int]) -> (String, Int)? {
    guard !counts.isEmpty else { return nil }
    return counts.keys.sorted {
        let left = counts[$0]!
        let right = counts[$1]!
        if left != right { return left > right }
        return $0 < $1
    }.first!
}

let mostErrorComponent = best(componentErrorCounts)
let componentName = mostErrorComponent?.0 ?? ""
let componentErrorCount = mostErrorComponent?.1 ?? 0

let busiestHour = best(hourCounts)
let busiestHourName = busiestHour?.0 ?? "00"
let busiestHourCount = busiestHour?.1 ?? 0

print("=== Log Analysis ===")
print()
print("Entries by Level:")
