use std::collections::{BTreeMap, BTreeSet};
use std::fs;

const LOG_PATH: &str = "/tmp/…/app.log";

struct Entry {
    hour: u32,
    level: String,
    component: String,
    message: String,
}

fn parse_line(line: &str) -> Option<Entry> {
    let open = line.find('[')?;
    let close_rel = line[open + 1..].find(']')?;
    let close = open + 1 + close_rel;
    let timestamp = &line[open + 1..close];
    let mut rest = &line[close + 1..].trim_start();

    let level_end = rest.find(' ')?;
    let level = &rest[..level_end];
    rest = &rest[level_end + 1..];

    let comp_open = rest.find('(')?;
    let comp_close_rel = rest[comp_open..].find(')')?;
    let comp_close = comp_open + comp_close_rel;
    let component = &rest[comp_open + 1..comp_close];

    rest = &rest[comp_close + 1..].trim_start();
    let sep = rest.find(" - ")?;
    let message = &rest[sep + 3..];

    let hour_token = timestamp.split(' ').nth(1)?;
    let hour: u32 = hour_token.split(':').next()?.parse().ok()?;

    Some(Entry {
        hour,
        level: level.to_string(),
        component: component.to_string(),
        message: message.to_string(),
    })
}

fn main() {
    let bytes = fs::read(LOG_PATH).ok().unwrap_or_default();
    let content = String::from_utf8_lossy(&bytes).to_string();

    let mut levels: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_components: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hours: BTreeMap<u32, usize> = BTreeMap::new();

    for raw_line in content.lines() {
        let line = raw_line.trim();
        if line.is_empty() {
            continue;
        }

        if let Some(entry) = parse_line(line) {
            *levels.entry(entry.level.clone()).or_insert(0) += 1;
            hours.entry(entry.hour).or_insert(0) += 1;

            if entry.level == "ERROR" {
                *error_components.entry(entry.component.clone()).or_insert(0) += 1;
                error_messages.insert(entry.message.clone());
            }
        }
    }

    let mut max_component = String::new();
    let mut max_errors = 0;
    for (component, count) in &error_components {
        if *count > max_errors {
            max_errors = *count;
            max_component = component.clone();
        }
    }

    let mut busiest_hour = 0u32;
    let mut busiest_count = 0;
    for (hour, count) in &hours {
        if *count > busiest_count {
            busiest_count = *count;
            busiest_hour = hour;
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &levels {
        println!("  {}: {}", level, count);
    }
    println!();
    println!("Component with Most Errors: {} ({})", max_component, max_errors);
    println!();
    println!("Unique Error Messages:");
    for message in &error_messages {
        println!("  - {}", message);
    }
    println!();
    println!("Busiest Hour: {}:00 ({})", format!("{:02}", busiest_hour), busiest_count);
}

