declare const fetch: any;
declare const console: any;
declare const require: any;

const url = "http://127.0.0.1:18923/api/products";

function printFiltered(products: Array<{ name: string; price: number }>): void {
  const lines: string[] = [
    "=== Filtered Products (price > $50.00) ===",
    ""
  ];

  let total = 0;
  for (const product of products) {
    lines.push(`${product.name}: $${product.price.toFixed(2)}`);
    total += product.price;
  }

  lines.push("");
  lines.push(`Count: ${products.length}`);
  lines.push(`Total: $${total.toFixed(2)}`);

  console.log(lines.join("\n"));
}

function printEmpty(): void {
  printFiltered([]);
}

function handleData(data: any): void {
  if (!Array.isArray(data)) {
    printEmpty();
    return;
  }

  const filtered: Array<{ name: string; price: number }> = [];

  for (const item of data) {
    if (item && typeof item === "object") {
      const price = Number(item.price);
      if (price > 50) {
        filtered.push({ name: String(item.name), price });
      }
    }
  }

  filtered.sort((a, b) => {
    if (a.name < b.name) return -1;
    if (a.name > b.name) return 1;
    return 0;
  });

  printFiltered(filtered);
}

function handleJsonResponse(response: any): void {
  try {
    response.json().then(handleData).catch(() => printEmpty());
  } catch {
    printEmpty();
  }
}

function main(): void {
  if (typeof fetch === "function") {
    fetch(url).then(handleJsonResponse).catch(() => printEmpty());
  } else if (typeof require === "function") {
    let http: any;

    try {
      http = require("http");
    } catch {
      printEmpty();
      return;
    }

    if (!http) {
      printEmpty();
      return;
    }

    try {
      http.get(url, (response: any) => {
        if (typeof response.on !== "function") {
          printEmpty();
          return;
        }

        let body = "";

        if (typeof response.setEncoding === "function") {
          response.setEncoding("utf8");
        }

        response.on("data", (chunk: any) => {
          body += chunk;
        });

        response.on("end", () => {
          try {
            handleData(JSON.parse(body));
          } catch {
            printEmpty();
          }
        });
      }).on("error", () => printEmpty());
    } catch {
      printEmpty();
    }
  } else {
    printEmpty();
  }
}

