const csvPath = '/tmp/…/employees.csv';

function parseCsv(text: string): string[][] {
    const rows: string[][] = [];
    let row: string[] = [];
    let field = '';
    let i = 0;
    let inQuotes = false;

    while (i < text.length) {
        const ch = text.charAt(i);

        if (inQuotes) {
            if (ch === '"') {
                if (i + 1 < text.length && text.charAt(i + 1) === '"') {
                    field += '"';
                    i += 2;
                } else {
                    inQuotes = false;
                    i++;
                }
            } else {
                field += ch;
                i++;
            }
        } else {
            if (ch === '"') {
                inQuotes = true;
                i++;
            } else if (ch === ',') {
                row.push(field);
                field = '';
                i++;
            } else if (ch === '\r' || ch === '\n') {
                if (ch === '\r' && i + 1 < text.length && text.charAt(i + 1) === '\n') {
                    i++;
                }
                if (row.length > 0 || field !== '') {
                    rows.push(row);
                }
                row = [];
                field = '';
                i++;
            } else {
                field += ch;
                i++;
            }
        }
    }

    if (row.length > 0 || field !== '') {
        rows.push(row);
    }

    return rows;
}

function addCommas(intPart: string): string {
    return intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function formatMoney(value: number, decimals: number): string {
    const negative = value < 0;
    const abs = Math.abs(value);
    const fixed = abs.toFixed(decimals);
    const dotIndex = fixed.indexOf('.');
    let intPart: string;
    let fracPart: string;

    if (dotIndex >= 0) {
        intPart = fixed.slice(0, dotIndex);
        fracPart = fixed.slice(dotIndex + 1);
    } else {
        intPart = fixed;
        fracPart = '';
    }

    const body = addCommas(intPart) + (decimals > 0 ? '.' + fracPart : '');
    return (negative ? '-' : '') + '$' + body;
}

function parseSalary(raw: string): number {
    let s = raw.trim();
    s = s.replace(/[$,]/g, '');
    const n = Number(s);
    if (isNaN(n)) {
        return 0;
    }
    return n;
}

function columnIndex(headers: string[], name: string, fallback: number): number {
    const idx = headers.indexOf(name);
    return idx >= 0 ? idx : fallback;
}

function compareDepartments(a: { dept: string }, b: { dept: string }): number {
    const al = a.dept.toLowerCase();
    const bl = b.dept.toLowerCase();
    if (al < bl) return -1;
    if (al > bl) return 1;
    if (a.dept < b.dept) return -1;
    if (a.dept > b.dept) return 1;
    return 0;
}

let csvContent = '';
try {
    const fs = require('fs');
    csvContent = fs.readFileSync(csvPath, 'utf8');
} catch (err) {
    csvContent = '';
}

let text = csvContent;
if (text.length > 0 && text.charCodeAt(0) === 0xfeff) {
    text = text.substring(1);
}

const rows = parseCsv(text);

let headers: string[] = [];
let dataRows: string[][] = rows;

if (rows.length > 0) {
    const firstRow = rows[0].map(function (h) {
        return h.trim().toLowerCase();
    });

    const hasHeader =
        firstRow.indexOf('employee_id') >= 0 &&
        firstRow.indexOf('name') >= 0 &&
        firstRow.indexOf('department') >= 0 &&
        firstRow.indexOf('salary') >= 0;

    if (hasHeader) {
        headers = firstRow;
        dataRows = rows.slice(1);
    }
}

const nameIndex = columnIndex(headers, 'name', 1);
const deptIndex = columnIndex(headers, 'department', 2);
const salaryIndex = columnIndex(headers, 'salary', 3);

const departments: { dept: string; sum: number; count: number }[] = [];

function getDepartment(dept: string): { dept: string; sum: number; count: number } {
    for (let i = 0; i < departments.length; i++) {
        if (departments[i].dept === dept) {
            return departments[i];
        }
    }

    const stat = { dept: dept, sum: 0, count: 0 };
    departments.push(stat);
    return stat;
}

let totalBudget = 0;
let highestName = '';
let highestSalary = -Infinity;

for (let r = 0; r < dataRows.length; r++) {
    const row = dataRows[r];

    if (row.length <= nameIndex || row.length <= deptIndex || row.length <= salaryIndex) {
        continue;
    }

    const name = row[nameIndex].trim();
    const dept = row[deptIndex].trim();
    const salary = parseSalary(row[salaryIndex]);

    totalBudget += salary;

    const stat = getDepartment(dept);
    stat.sum += salary;
    stat.count++;

    if (salary > highestSalary) {
        highestSalary = salary;
        highestName = name;
    }
}

if (highestSalary === -Infinity) {
    highestName = 'N/A';
    highestSalary = 0;
}

const sortedDepartments = departments.slice(0).sort(compareDepartments);
const overTwo = sortedDepartments.filter(function (s) {
    return s.count > 2;
});

const outputLines: string[] = [];
outputLines.push('=== Salary Report ===');
outputLines.push('');
outputLines.push('Average Salary by Department:');

for (let i = 0; i < sortedDepartments.length; i++) {
    const avg = sortedDepartments[i].sum / sortedDepartments[i].count;
    outputLines.push('  ' + sortedDepartments[i].dept + ': ' + formatMoney(avg, 2));
}

outputLines.push('');
outputLines.push('Highest Paid: ' + highestName + ' (' + formatMoney(highestSalary, 0) + ')');

outputLines.push('');
outputLines.push('Departments with >2 employees:');

for (let i = 0; i < overTwo.length; i++) {
    outputLines.push('  ' + overTwo[i].dept + ' (' + overTwo[i].count + ' employees)');
}

outputLines.push('');
outputLines.push('Total Budget: ' + formatMoney(totalBudget, 0));

process.stdout.write(outputLines.join('\n') + '\n');

import json
import heapq


def main():
    graph_path = "/tmp/…/graph.json"

    with open(graph_path, "r") as f:
        data = json.load(f)

    nodes = data.get("nodes", [])
    edges = data.get("edges", [])

    adjacency = {node: [] for node in nodes}

    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        weight = edge["weight"]

        if u in adjacency and v in adjacency:
            adjacency[u].append((v, weight))
            adjacency[v].append((u, weight))

    start = "A"
    distances = {node: float("inf") for node in nodes}

    if start not in distances:
        distances[start] = float("inf")

    distances[start] = 0

    heap = [(0, start)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        if current_distance > distances.get(current_node, float("inf")):
            continue

        for neighbor, weight in adjacency.get(current_node, []):
            new_distance = current_distance + weight

            if new_distance < distances.get(neighbor, float("inf")):
                distances[neighbor] = new_distance
                heapq.heappush(heap, (new_distance, neighbor))

    print("=== Shortest Paths from A ===")
    print()

    for node in sorted(distances):
        print(f"A -> {node}: {distances[node]}")


if __name__ == "__main__":
    main()

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.NumberFormat;
import java.util.TreeMap;

public class Main {
    private static final String CSV_PATH = "/tmp/…/employees.csv";

    public static void main(String[] args) throws IOException {
        Map<String, Accumulator> departments = new TreeMap<>();
        BigDecimal totalBudget = BigDecimal.ZERO;

        boolean hasEmployee = false;
        String highestPaidName = "N/A";
        BigDecimal highestPaidSalary = BigDecimal.ZERO;

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(CSV_PATH), StandardCharsets.UTF_8))) {
            String line;
            boolean firstMeaningfulLine = true;

            while ((line = reader.readLine()) != null) {
                if (line.trim().isEmpty()) {
                    continue;
                }

                boolean first = firstMeaningfulLine;
                if (first) {
                    line = stripBom(line);
                    firstMeaningfulLine = false;
                }

                String[] fields = parseCsvLine(line);

                if (first && fields.length >= 1 && fields[0].trim().equalsIgnoreCase("employee_id")) {
                    continue;
                }

                if (fields.length < 6) {
                    continue;
                }

                String name = fields[1].trim();
                String department = fields[2].trim();
                String salaryText = fields[3].trim();

                BigDecimal salary;
                try {
                    salary = new BigDecimal(salaryText);
                } catch (NumberFormatException e) {
                    continue;
                }

                Accumulator accumulator = departments.get(department);
                if (accumulator == null) {
                    accumulator = new Accumulator();
                    departments.put(department, accumulator);
                }

                accumulator.sum.add(salary);
                accumulator.count++;
                totalBudget.add(salary);

                if (!hasEmployee || salary.compareTo(highestPaidSalary) > 0) {
                    hasEmployee = true;
                    highestPaidSalary = salary;
                    highestPaidName = name;
                }
            }
        }

        StringBuilder output = new StringBuilder();

        output.append("=== Salary Report ===\n\n");
        output.append("Average Salary by Department:\n");

        for (Map.Entry<String, Accumulator> entry : departments.entrySet()) {
            Accumulator accumulator = entry.getValue();
            BigDecimal average = accumulator.sum.divide(accumulator.count, 2, RoundingMode.HALF_UP);
            output.append("  Department: ").append(formatAverage(average)).append('\n');
        }

        output.append('\n');
        output.append("Highest Paid: ").append(highestPaidName)
                .append(" ($").append(formatInteger(highestPaidSalary)).append(")\n\n");

        output.append("Departments with >2 employees:\n");
        for (Map.Entry<String, Accumulator> entry : departments.entrySet()) {
            Accumulator accumulator = entry.getValue();
            if (accumulator.count > 2) {
                output.append("  ").append(entry.getKey())
                        .append(" (").append(accumulator.count).append(" employees)\n");
            }
        }

        output.append('\n');
        output.append("Total Budget: ").append(formatInteger(totalBudget)).append('\n');

        System.out.print(output.toString());
    }

    private static String formatAverage(BigDecimal value) {
        NumberFormat format = NumberFormat.getInstance(Locale.US);
        format.setMinimumFractionDigits(2);
        format.setMaximumFractionDigits(2);
        format.setRoundingMode(RoundingMode.HALF_UP);
        format.setGroupingOverride(true);
        return "$" + format.format(value);
    }

    private static String formatInteger(BigDecimal value) {
        BigDecimal scaled = value.setScale(0, RoundingMode.HALF_UP);
        NumberFormat format = NumberFormat.getInstance(Locale.US);
        format.setMinimumFractionDigits(0);
        format.setMaximumFractionDigits(0);
        format.setRoundingMode(RoundingMode.HALF_UP);
        format.setGroupingOverride(true);
        return "$" + format.format(scaled);
    }

    private static String parseCsvLine(String line) {
        List<String> fields = new ArrayList<>();
        StringBuilder field = new StringBuilder();
        boolean inQuotes = false;

        int i = 0;
        while (i < line.length()) {
            char c = line.charAt(i);

            if (inQuotes) {
                if (c == '"') {
                    if (i + 1 < line.length() && line.charAt(i + 1) == '"') {
                        field.append('"');
                        i += 2;
                    } else {
                        inQuotes = false;
                        i++;
                    }
                } else {
                    field.append(c);
                    i++;
                }
            } else {
                if (c == '"') {
                    inQuotes = true;
                    i++;
                } else if (c == ',') {
                    fields.add(field.toString());
                    field.clear();
                    i++;
                } else {
                    field.append(c);
                    i++;
                }
            }
        }

        fields.add(field.toString());
        return fields;
    }

    private static String stripBom(String line) {
        return line.startsWith("\uFEFF") ? line.substring(1) : line;
    }

    private static class Accumulator {
        BigDecimal sum;
        int count;

        Accumulator() {
            sum = BigDecimal.ZERO;
            count = 0;
        }
    }
}

