        private Json parseValue() {
            skipWhitespace();

            if (index >= text.length()) {
                throw new IllegalArgumentException("Unexpected end of JSON input");
            }

            char c = text.charAt(index);

            if (c == '{') {
                return parseObject();
            }
            if (c == '[') {
                return parseArray();
            }
            if (c == '"') {
                return parseString();
            }
            if (c == '-' || c == '+' || Character.isDigit(c)) {
                return parseNumber();
            }
            if (text.startsWith("true", index)) {
                index += 4;
                return new Json(true);
            }
            if (text.startsWith("false", index)) {
                index += 5;
                return new Json(false);
            }
            if (text.startsWith("null", index)) {
                index += 4;
                return new Json(null);
            }

            throw new IllegalArgumentException("Unexpected character '" + c + "' at position " + index);
        }

        private Json parseObject() {
            expect('{');
            Map<String, Json> object = new LinkedHashMap<>();

            skipWhitespace();
            if (index < text.length() && text.charAt(index) == '}') {
                index++;
                return new Json(object);
            }

            while (true) {
                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                String key = parseString();
                expect(':');

                skipWhitespace();
                Json value = parseValue();

                object.put(key, value);

                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                char c = text.charAt(index);
                if (c == ',') {
                    index++;
                    continue;
                }
                if (c == '}') {
                    index++;
                    break;
                }

                throw new IllegalArgumentException("Expected ',' or '}' at position " + index);
            }

            return new Json(object);
        }

        private Json parseArray() {
            expect('[');
            List<Json> array = new ArrayList<>();

            skipWhitespace();
            if (index < text.length() && text.charAt(index) == ']') {
                index++;
                return new Json(array);
            }

            while (true) {
                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                array.add(parseValue());

                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                char c = text.charAt(index);
                if (c == ',') {
                    index++;
                    continue;
                }
                if (c == ']') {
                    index++;
                    break;
                }

                throw new IllegalArgumentException("Expected ',' or ']' at position " + index);
            }

            return new Json(array);
        }

        private Json parseString() {
            expect('"');
            StringBuilder builder = new StringBuilder();

            while (index < text.length()) {
                char c = text.charAt(index++);

                if (c == '"') {
                    return new Json(builder.toString());
                }

                if (c == '\\') {
                    if (index >= text.length()) {
                        break;
                    }

                    char escape = text.charAt(index++);
                    switch (escape) {
                        case '"':
                            builder.append('"');
                            break;
                        case '\\':
                            builder.append('\\');
                            break;
                        case '/':
                            builder.append('/');
                            break;
                        case 'b':
                            builder.append('\b');
                            break;
                        case 'f':
                            builder.append('\f');
                            break;
                        case 'n':
                            builder.append('\n');
                            break;
                        case 'r':
                            builder.append('\r');
                            break;
                        case 't':
                            builder.append('\t');
                            break;
                        case 'u':
                            int code = 0;
                            for (int i = 0; i < 4; i++) {
                                if (index >= text.length()) {
                                    break;
                                }
                                code = code * 16 + Character.digit(text.charAt(index++), 16);
                            }
                            builder.append((char) code);
                            break;
                        default:
                            builder.append(escape);
                    }
                } else {
                    builder.append(c);
                }
            }

            return new Json(builder.toString());
        }

        private Json parseNumber() {
            int start = index;

            if (index < text.length() && (text.charAt(index) == '-' || text.charAt(index) == '+')) {
                index++;
            }

            while (index < text.length() && Character.isDigit(text.charAt(index))) {
                index++;
            }

            if (index < text.length() && text.charAt(index) == '.') {
                index++;
                while (index < text.length() && Character.isDigit(text.charAt(index))) {
                    index++;
                }
            }

            if (index < text.length() && (text.charAt(index) == 'e' || text.charAt(index) == 'E')) {
                index++;

                if (index < text.length() && (text.charAt(index) == '-' || text.charAt(index) == '+')) {
                    index++;
                }

                while (index < text.length() && Character.isDigit(text.charAt(index))) {
                    index++;
                }
            }

            return new Json(Double.parseDouble(text.substring(start, index)));
        }
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;

public class Main {
    private static final String INPUT_PATH =
        "/tmp/…/graph.json";

    public static void main(String[] args) throws Exception {
        String json = new String(Files.readAllBytes(Paths.get(INPUT_PATH)), StandardCharsets.UTF_8);

        Object root = new Parser(json).parse();
        Map<?, ?> rootMap = (Map<?, ?>) root;

        List<String> nodes = new ArrayList<>();
        Object nodesValue = rootMap.get("nodes");
        if (nodesValue instanceof List) {
            for (Object item : (List<?>) nodesValue) {
                if (item instanceof String) {
                    nodes.add((String) item);
                }
            }
        }

        List<String> uniqueNodes = new ArrayList<>(new LinkedHashSet<>(nodes));
        nodes.clear();
        nodes.addAll(uniqueNodes);

        Map<String, List<Edge>> graph = new HashMap<>();
        for (String node : nodes) {
            graph.put(node, new ArrayList<>());
        }

        Object edgesValue = rootMap.get("edges");
        if (edgesValue instanceof List) {
            for (Object item : (List<?>) edgesValue) {
                if (item instanceof Map) {
                    Map<?, ?> edgeMap = (Map<?, ?>) item;
                    String from = stringValue(edgeMap, "from");
                    String to = stringValue(edgeMap, "to");

                    if (from != null && to != null) {
                        double weight = numberValue(edgeMap, "weight");

                        addNodeIfAbsent(nodes, from);
                        addNodeIfAbsent(nodes, to);

                        graph.computeIfAbsent(from, k -> new ArrayList<>());
                        graph.computeIfAbsent(to, k -> new ArrayList<>());

                        graph.get(from).add(new Edge(to, weight));
                        if (!from.equals(to)) {
                            graph.get(to).add(new Edge(from, weight));
                        }
                    }
                }
            }
        }

        if (!nodes.contains("A")) {
            nodes.add("A");
            graph.computeIfAbsent("A", k -> new ArrayList<>());
        }

        Map<String, Double> distance = new HashMap<>();
        distance.put("A", 0.0);

        PriorityQueue<State> pq = new PriorityQueue<>(Comparator.comparingDouble(s -> s.dist));
        pq.offer(new State("A", 0.0));

        while (!pq.isEmpty()) {
            State current = pq.poll();
            Double best = distance.get(current.node);

            if (best == null || current.dist > best + 1e-12) {
                continue;
            }

            List<Edge> neighbors = graph.getOrDefault(current.node, Collections.emptyList());
            for (Edge edge : neighbors) {
                double nextDistance = current.dist + edge.weight;
                Double oldDistance = distance.get(edge.to);

                if (oldDistance == null || nextDistance < oldDistance - 1e-12) {
                    distance.put(edge.to, nextDistance);
                    pq.offer(new State(edge.to, nextDistance));
                }
            }
        }

        Collections.sort(nodes);

        StringBuilder output = new StringBuilder();
        output.append("=== Shortest Paths from A ===\n\n");

        for (String node : nodes) {
            output.append("A -> ")
                    .append(node)
                    .append(": ")
                    .append(formatDistance(distance.get(node)))
                    .append('\n');
        }

        System.out.print(output.toString());
    }

    private static void addNodeIfAbsent(List<String> nodes, String node) {
        if (!nodes.contains(node)) {
            nodes.add(node);
        }
    }

    private static String stringValue(Map<?, ?> map, String key) {
        Object value = map.get(key);
        return value instanceof String ? (String) value : null;
    }

    private static double numberValue(Map<?, ?> map, String key) {
        Object value = map.get(key);
        if (value instanceof Number) {
            return ((Number) value).doubleValue();
        }
        if (value instanceof String) {
            return Double.parseDouble((String) value);
        }
        throw new IllegalArgumentException("Missing or invalid numeric value for " + key);
    }

    private static String formatDistance(Double value) {
        if (value == null || Double.isNaN(value) || Double.isInfinite(value)) {
            return "Infinity";
        }

        if (Math.abs(value - Math.rint(value)) < 1e-9) {
            return String.valueOf((long) Math.rint(value));
        }

        return String.format(Locale.US, "%.15g", value);
    }

    private static class Edge {
        final String to;
        final double weight;

        Edge(String to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    private static class State {
        final String node;
        final double dist;

        State(String node, double dist) {
            this.node = node;
            this.dist = dist;
        }
    }

    private static class Parser {
        private final String text;
        private int index = 0;

        Parser(String text) {
            this.text = text;
        }

        Object parse() {
            skipWhitespace();
            Object result = parseValue();
            skipWhitespace();

            if (index < text.length()) {
                throw new IllegalArgumentException("Unexpected trailing data at position " + index);
            }

            return result;
        }

        private void skipWhitespace() {
            while (index < text.length() && Character.isWhitespace(text.charAt(index))) {
                index++;
            }
        }

        private void expect(char expected) {
            skipWhitespace();
            if (index >= text.length() || text.charAt(index) != expected) {
                throw new IllegalArgumentException("Expected '" + expected + "' at position " + index);
            }
            index++;
        }

        private Object parseValue() {
            skipWhitespace();

            if (index >= text.length()) {
                throw new IllegalArgumentException("Unexpected end of JSON input");
            }

            char c = text.charAt(index);

            if (c == '{') {
                return parseObject();
            }
            if (c == '[') {
                return parseArray();
            }
            if (c == '"') {
                return parseString();
            }
            if (c == '-' || c == '+' || Character.isDigit(c)) {
                return parseNumber();
            }
            if (text.startsWith("true", index)) {
                index += 4;
                return Boolean.TRUE;
            }
            if (text.startsWith("false", index)) {
                index += 5;
                return Boolean.FALSE;
            }
            if (text.startsWith("null", index)) {
                index += 4;
                return null;
            }

            throw new IllegalArgumentException("Unexpected character '" + c + "' at position " + index);
        }

        private Map<String, Object> parseObject() {
            expect('{');
            Map<String, Object> object = new LinkedHashMap<>();

            skipWhitespace();
            if (index < text.length() && text.charAt(index) == '}') {
                index++;
                return object;
            }

            while (true) {
                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                String key = parseString();
                expect(':');

                skipWhitespace();
                Object value = parseValue();

                object.put(key, value);

                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                char c = text.charAt(index);
                if (c == ',') {
                    index++;
                    continue;
                }
                if (c == '}') {
                    index++;
                    break;
                }

                throw new IllegalArgumentException("Expected ',' or '}' at position " + index);
            }

            return object;
        }

        private List<Object> parseArray() {
            expect('[');
            List<Object> array = new ArrayList<>();

            skipWhitespace();
            if (index < text.length() && text.charAt(index) == ']') {
                index++;
                return array;
            }

            while (true) {
                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                array.add(parseValue());

                skipWhitespace();
                if (index >= text.length()) {
                    throw new IllegalArgumentException("Unexpected end of JSON input");
                }

                char c = text.charAt(index);
                if (c == ',') {
                    index++;
                    continue;
                }
                if (c == ']') {
                    index++;
                    break;
                }

                throw new IllegalArgumentException("Expected ',' or ']' at position " + index);
            }

            return array;
        }

        private String parseString() {
            expect('"');
            StringBuilder builder = new StringBuilder();

            while (index < text.length()) {
                char c = text.charAt(index++);

                if (c == '"') {
                    return builder.toString();
                }

                if (c == '\\') {
                    if (index >= text.length()) {
                        break;
                    }

                    char escape = text.charAt(index++);
                    switch (escape) {
                        case '"':
                            builder.append('"');
                            break;
                        case '\\':
                            builder.append('\\');
                            break;
                        case '/':
                            builder.append('/');
                            break;
                        case 'b':
                            builder.append('\b');
                            break;
                        case 'f':
                            builder.append('\f');
                            break;
                        case 'n':
                            builder.append('\n');
                            break;
                        case 'r':
                            builder.append('\r');
                            break;
                        case 't':
                            builder.append('\t');
                            break;
                        case 'u':
                            int code = 0;
                            for (int i = 0; i < 4; i++) {
                                if (index >= text.length()) {
                                    break;
                                }
                                code = code * 16 + Character.digit(text.charAt(index++), 16);
                            }
                            builder.append((char) code);
                            break;
                        default:
                            builder.append(escape);
                    }
                } else {
                    builder.append(c);
                }
            }

            return builder.toString();
        }

        private double parseNumber() {
            int start = index;
            int digits = 0;

            if (index < text.length() && (text.charAt(index) == '-' || text.charAt(index) == '+')) {
                index++;
            }

            while (index < text.length() && Character.isDigit(text.charAt(index))) {
                index++;
                digits++;
            }

            if (index < text.length() && text.charAt(index) == '.') {
                index++;
                while (index < text.length() && Character.isDigit(text.charAt(index))) {
                    index++;
                    digits++;
                }
            }

            if (index < text.length() && (text.charAt(index) == 'e' || text.charAt(index) == 'E')) {
                index++;

                if (index < text.length() && (text.charAt(index) == '-' || text.charAt(index) == '+')) {
                    index++;
                }

                while (index < text.length() && Character.isDigit(text.charAt(index))) {
                    index++;
                    digits++;
                }
            }

            if (digits == 0) {
                throw new IllegalArgumentException("Invalid number at position " + start);
            }

            return Double.parseDouble(text.substring(start, index));
        }
    }
}

