}

func parsePrice(_ value: Any?) -> Double? {
    guard let value = value else { return nil }
    if let number = value as? NSNumber {
        return number.doubleValue
    }
    if let text = value as? String, let number = Double(text) {
        return number
    }
    return nil
}

func fetchProducts() -> [Product] {
    guard let url = URL(string: "http://127.0.0.1:18923/api/products") else {
        return []
    }

    let semaphore = DispatchSemaphore(value: 0)
    var responseData: Data?
    var responseError: Error?

    URLSession.shared.dataTask(with: url) { data, error, _ in
        responseData = data
        responseError = error
        semaphore.signal()
    }.resume()

    semaphore.wait(timeout: .none)

    guard let jsonData = responseData, responseError == nil else {
        return []
    }

    guard let jsonObject = try? JSONSerialization.jsonObject(with: jsonData),
