    let price: Double
}

func parsePrice(_ value: Any?) -> Double? {
    guard let value = value else { return nil }

    if let number = value as? NSNumber {
        return number.doubleValue
    }

    if let text = value as? String {
        let trimmed = text.trimmingCharacters(in: .whitespaces)
        if let number = Double(trimmed) {
            return number
        }
    }

    if let number = value as? Int {
        return Double(number)
    }

    if let number = value as? Double {
        return number
    }

    return nil
}

func fetchProducts() -> [Product] {
    guard let url = URL(string: "http://127.0.0.1:18923/api/products") else {
        return []
    }

    let semaphore = DispatchSemaphore(value: 0)
    var responseData: Data?
    var responseError: Error? = nil

    let request = URLRequest(url: url)
    request.timeoutInterval = 10

    URLSession.shared.dataTask(with: request) { data, error, _ in
        responseData = data
        responseError = error
        semaphore.signal()
    }.resume()

    guard semaphore.wait(timeout: .now(seconds: 10)) == true else {
        return []
    }

    guard let jsonData = responseData, responseError == nil else {
        return []
    }

    guard let jsonObject = try? JSONSerialization.jsonObject(with: jsonData) else {
        return []
    }

    guard let jsonArray = jsonObject as? [Any] else {
        return []
    }

    var products: [Product] = []
    for element in jsonArray {
        guard let dict = element as? [String: Any] else { continue }
        guard let name = dict["name"] as? String else { continue }
        guard let price = parsePrice(dict["price"]), price > 50.0 else { continue }
        products.append(Product(name: name, price: price))
    }

    return products
}

func formatPrice(_ value: Double) -> String {
    return String(format: "%.2f", value, locale: Locale(identifier: "en_US_POSIX"))
}

func printReport(products: [Product]) {
    var products = products
    products.sort { $0.name < $1.name }

    var total: Double = 0.0
    var outputLines: [String] = [
        "=== Filtered Products (price > $50.00) ===",
        ""
    ]

    for product in products {
        total += product.price
        outputLines.append("\(product.name): $\(formatPrice(product.price))")
    }

    outputLines.append("")
    outputLines.append("Count: \(products.count)")
    outputLines.append("Total: \(\(formatPrice(total))")

    print(outputLines.joined(separator: "\n"))
}

