#define CSV_PATH "/tmp/…/employees.csv"

typedef struct {
    char *name;
    double sum;
    size_t count;
} Dept;

static void ensure_append(char **buf, size_t *len, size_t *cap, char c) {
    if (*len + 1 >= *cap) {
        size_t newcap = *cap ? *cap * 2 : 16;
        char *nb = realloc(*buf, newcap);
        if (!nb) {
            exit(EXIT_FAILURE);
        }
        *buf = nb;
        *cap = newcap;
    }
    (*buf)[(*len)++] = c;
}

static char *xstrdup(const char *s) {
    if (!s) {
        s = "";
    }
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (!p) {
        exit(EXIT_FAILURE);
    }
    memcpy(p, s, n);
    return p;
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        return NULL;
    }

    size_t cap = 8192;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) {
        fclose(f);
        return NULL;
    }

    int c;
    while ((c = fgetc(f)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) {
                free(buf);
                fclose(f);
                return NULL;
            }
            buf = nb;
        }
        buf[len++] = (char)c;
    }

    buf[len] = '\0';

    if (len >= 3 &&
        (unsigned char)buf[0] == 0xEF &&
        (unsigned char)buf[1] == 0xBB &&
        (unsigned char)buf[2] == 0xBF) {
        memmove(buf, buf + 3, len - 3);
        buf[len - 3] = '\0';
        len -= 3;
    }

    *out_len = len;
    fclose(f);
    return buf;
}

static char *trim_field(char *s) {
    if (!s) {
        return s;
    }

    char *start = s;
    while (*start && isspace((unsigned char)*start)) {
        start++;
    }

    char *end = start + strlen(start);
    while (end > start && isspace((unsigned char)end[-1])) {
        end--;
    }

    *end = '\0';
    return start;
}

static int parse_salary(const char *s, double *out) {
    if (!s) {
        return 0;
    }

    size_t n = strlen(s);
    char *t = malloc(n + 1);
    if (!t) {
        exit(EXIT_FAILURE);
    }

    size_t j = 0;
    for (size_t i = 0; i < n; ++i) {
        char c = s[i];
        if (isspace((unsigned char)c) || c == '$' || c == ',') {
            continue;
        }
        t[j++] = c;
    }
    t[j] = '\0';

    if (t[0] == '\0') {
        free(t);
        return 0;
    }

    char *end = NULL;
    double v = strtod(t, &end);
    size_t tlen = strlen(t);

    if (end == t || end != t + tlen || !isfinite(v)) {
        free(t);
        return 0;
    }

    *out = v;
    free(t);
    return 1;
}

static char **parse_record(const char *buf, size_t len, size_t *pos, size_t *out_fields) {
    char **fields = NULL;
    size_t count = 0;
    size_t cap = 0;
    int started = 0;

    while (*pos < len) {
        if (!started) {
            if (buf[*pos] == '\n' || buf[*pos] == '\r') {
                (*pos)++;
                continue;
            }
            started = 1;
        }

        char *field = (char *)malloc(1);
        if (!field) {
            exit(EXIT_FAILURE);
        }
        field[0] = '\0';
        size_t flen = 0;
        size_t fcap = 1;

        if (buf[*pos] == '\n' || buf[*pos] == '\r') {
            field = trim_field(field);
            if (count == cap) {
                cap = cap ? cap * 2 : 8;
                fields = (char **)realloc(fields, cap * sizeof(char *));
                if (!fields) {
                    exit(EXIT_FAILURE);
                }
            }
            fields[count++] = field;
            break;
        }

        if (buf[*pos] == '"') {
            (*pos)++;
            while (*pos < len) {
                char c = buf[*pos];
                if (c == '"') {
                    if (*pos + 1 < len && buf[*pos + 1] == '"') {
                        ensure_append(&field, &flen, &fcap, c);
                        (*pos) += 2;
                    } else {
                        (*pos)++;
                        break;
                    }
                } else {
                    ensure_append(&field, &flen, &fcap, c);
                    (*pos)++;
                }
            }

            if (*pos < len && buf[*pos] != ',' && buf[*pos] != '\n' && buf[*pos] != '\r') {
                while (*pos < len && buf[*pos] != ',' && buf[*pos] != '\n' && buf[*pos] != '\r') {
                    ensure_append(&field, &flen, &fcap, buf[*pos]);
                    (*pos)++;
                }
            }
        } else {
            while (*pos < len) {
                char c = buf[*pos];
                if (c == ',' || c == '\n' || c == '\r') {
                    break;
                }
                ensure_append(&field, &flen, &fcap, c);
                (*pos)++;
            }
        }

        field = trim_field(field);

        if (count == cap) {
            cap = cap ? cap * 2 : 8;
            fields = (char **)realloc(fields, cap * sizeof(char *));
            if (!fields) {
                exit(EXIT_FAILURE);
            }
        }
        fields[count++] = field;

        if (*pos < len && buf[*pos] == ',') {
            (*pos)++;
            if (*pos >= len) {
                char *empty = (char *)malloc(1);
                if (!empty) {
                    exit(EXIT_FAILURE);
                }
                empty[0] = '\0';

                if (count == cap) {
                    cap = cap ? cap * 2 : 8;
                    fields = (char **)realloc(fields, cap * sizeof(char *));
                    if (!fields) {
                        exit(EXIT_FAILURE);
                    }
                }
                fields[count++] = empty;
                break;
            }
            continue;
        }

        break;
    }

    *out_fields = fields;
    return fields;
}

static void add_department(Dept **deps, size_t *count, size_t *cap, const char *name) {
    for (size_t i = 0; i < *count; ++i) {
        if (strcmp((*deps)[i].name, name) == 0) {
            return;
        }
    }

    if (*count == *cap) {
        size_t newcap = *cap ? *cap * 2 : 8;
        *deps = (Dept *)realloc(*deps, newcap * sizeof(Dept));
        if (!*deps) {
            exit(EXIT_FAILURE);
        }
        *cap = newcap;
    }

    (*deps)[*count].name = xstrdup(name);
    (*deps)[*count].sum = 0.0;
    (*deps)[*count].count = 0;
    (*count)++;
}

static int compare_departments(const void *a, const void *b) {
    const Dept *da = (const Dept *)a;
    const Dept *db = (const Dept *)b;
    return strcmp(da->name, db->name);
}

static void format_unsigned(unsigned long long value, char *buf, size_t buflen) {
    char tmp[32];
    snprintf(tmp, sizeof(tmp), "%llu", value);

    size_t len = strlen(tmp);
    size_t outpos = 0;

    for (size_t i = 0; i < len; ++i) {
        if (i > 0 && ((len - i) % 3 == 0)) {
            if (outpos + 1 < buflen) {
                buf[outpos++] = ',';
            }
        }
        if (outpos < buflen) {
            buf[outpos++] = tmp[i];
        }
    }

    buf[outpos] = '\0';
}

static void format_integer(long long value, char *buf, size_t buflen) {
    if (value < 0) {
        if (buflen > 0) {
            buf[0] = '-';
        }
        format_unsigned(-(unsigned long long)value, buf + 1, buflen > 1 ? buflen - 1 : 1);
    } else {
        format_unsigned((unsigned long long)value, buf, buflen);
    }
}

static void format_average(double value, char *buf, size_t buflen) {
    char tmp[128];
    snprintf(tmp, sizeof(tmp), "%.2f", value);

    char *dot = strchr(tmp, '.');
    if (!dot) {
        snprintf(buf, buflen, "%s", tmp);
        return;
    }

    size_t int_len = (size_t)(dot - tmp);
    size_t outpos = 0;

    for (size_t i = 0; i < int_len; ++i) {
        if (i > 0 && ((int_len - i) % 3 == 0)) {
            if (outpos + 1 < buflen) {
                buf[outpos++] = ',';
            }
        }
        if (outpos < buflen) {
            buf[outpos++] = tmp[i];
        }
    }

    if (outpos < buflen) {
        buf[outpos++] = '.';
    }

    for (size_t i = int_len; i < strlen(tmp); ++i) {
        if (outpos < buflen) {
            buf[outpos++] = tmp[i];
        }
    }

    buf[outpos] = '\0';
}

