    size_t pos = 0;
    Dept *deps = NULL;
    size_t dept_count = 0;
    size_t dept_cap = 0;

    double total_salary = 0.0;
    double highest_salary = 0.0;
    int has_highest = 0;
    char *highest_name = xstrdup("None");

    int first_record = 1;

    while (pos < data_len) {
        size_t field_count = 0;
        char **fields = parse_record(data, data_len, &pos, &field_count);
        if (!fields) {
            continue;
        }

        if (first_record) {
            first_record = 0;
            double dummy;
            if (field_count >= 4 &&
                strcmp(fields[0], "employee_id") == 0 &&
                !parse_salary(fields[3], &dummy)) {
                for (size_t i = 0; i < field_count; ++i) {
                    free(fields[i]);
                }
                free(fields);
                continue;
            }
        }

        if (field_count < 4) {
            for (size_t i = 0; i < field_count; ++i) {
                free(fields[i]);
            }
            free(fields);
            continue;
        }

        const char *name = fields[1];
        const char *department = fields[2];
        const char *salary_str = fields[3];

        double salary;
        if (!parse_salary(salary_str, &salary)) {
            for (size_t i = 0; i < field_count; ++i) {
                free(fields[i]);
            }
            free(fields);
            continue;
        }

        total_salary += salary;

        if (!has_highest || salary > highest_salary) {
            has_highest = 1;
            highest_salary = salary;

            const char *display_name = (name && name[0] != '\0') ? name : "Unknown";
            char *new_name = xstrdup(display_name);
            free(highest_name);
            highest_name = new_name;
        }

        const char *display_department =
            (department && department[0] != '\0') ? department : "Unknown";

        Dept *d = add_department(&deps, &dept_count, &dept_cap, display_department);
        d->sum += salary;
        d->count++;

        for (size_t i = 0; i < field_count; ++i) {
            free(fields[i]);
        }
        free(fields);
    }

    if (dept_count > 0) {
        qsort(deps, dept_count, sizeof(Dept), compare_departments);
    }

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");

    for (size_t i = 0; i < dept_count; ++i) {
        double avg = dept_count > 0 ? 0.0 : 0.0;
        if (deps[i].count > 0) {
            avg = deps[i].sum / (double)deps[i].count;
        }

        char avg_str[128];
        format_average(avg, avg_str, sizeof(avg_str));
        printf("  %s: $%s\n", deps[i].name, avg_str);
    }

    printf("\n");

    char highest_str[128];
    format_integer(llround(highest_salary), highest_str, sizeof(highest_str));
    printf("Highest Paid: %s ($%s)\n", highest_name, highest_str);

    printf("\n");
    printf("Departments with >2 employees:\n");

    for (size_t i = 0; i < dept_count; ++i) {
        if (deps[i].count > 2) {
            printf("  %s (%zu employees)\n", deps[i].name, deps[i].count);
        }
    }

    printf("\n");

    char total_str[128];
    format_integer(llround(total_salary), total_str, sizeof(total_str));
    printf("Total Budget: $%s\n", total_str);

    for (size_t i = 0; i < dept_count; ++i) {
        free(deps[i].name);
    }
    free(deps);
    free(highest_name);
    free(data);

    return 0;
