            expectLiteral("false")
            return .bool(false)
        case 'n':
            expectLiteral("null")
            return .null
        case '-':
            return parseNumber()
        case '.':
            return parseNumber()
        default:
            if first >= "0" && first <= "9" {
                return parseNumber()
            }
            fatalError("Invalid JSON: unexpected character \(first)")
        }
    }

    private func parseNumber() -> JSONValue {
        let start = index
        if peek() == "-" {
            index += 1
        }

        let intStart = index
        parseUnsignedNumberPart()
        guard index > intStart else {
            fatalError("Invalid JSON: invalid number")
        }

        if peek() == "." {
            index += 1
            let fracStart = index
            parseUnsignedNumberPart()
            guard index > fracStart else {
                fatalError("Invalid JSON: invalid number fraction")
            }
        }

        if peek() == "e" || peek() == "E" {
            index += 1
            if peek() == "+" || peek() == "-" {
                index += 1
            }
            let expStart = index
            parseUnsignedNumberPart()
            guard index > expStart else {
                fatalError("Invalid JSON: invalid number exponent")
            }
