            fatalError("Invalid JSON unicode escape sequence")
        }

        if first >= 0xD800 && first <= 0xDBFF {
            guard index + 2 <= text.count,
                  text[index] == '\\',
                  text[index + 1] == 'u' else {
                fatalError("Invalid JSON surrogate pair")
            }

            index += 2

            guard let second = parseHex4(), second >= 0xDC00 && second <= 0xDFFF else {
                fatalError("Invalid JSON surrogate pair")
            }

            let code = 0x10000 + ((first - 0xD800) << 10) + (second - 0xDC00)
            out.append(Character(UnicodeScalar(code)))
        } else if first >= 0xDC00 && first <= 0xDFFF {
            fatalError("Invalid JSON: unexpected low surrogate")
        } else {
            out.append(Character(UnicodeScalar(first)))
        }
    }

    private func parseHex4() -> UInt32? {
        guard index + 4 <= text.count else { return nil }

        var value = 0
        for _ in 0..<4 {
            let c = text[index]
            index += 1

            guard let digit = hexDigit(c) else { return nil }
            value = value * 16 + digit
        }

        return value
    }

    private func hexDigit(_ c: Character) -> UInt32? {
        guard let ascii = c.asciiValue else { return nil }

        if ascii >= 48 && ascii <= 57 {
            return UInt32(ascii - 48)
        }

        if ascii >= 97 && ascii <= 102 {
            return UInt32(ascii - 97 + 10)
        }

        if ascii >= 65 && ascii <= 70 {
            return UInt32(ascii - 65 + 10)
        }

        return nil
    }
}

func merge(_ a: JSONValue, _ b: JSONValue) -> JSONValue {
    switch a {
    case .object(let aObject):
        if case .object(let bObject) = b {
            var result: [String: JSONValue] = [:]
            let keys = Array(aObject.keys).union(bObject.keys).sorted()

            for key in keys {
                if let aValue = aObject[key], let bValue = bObject[key] {
                    result[key] = merge(aValue, bValue)
                } else if let aValue = aObject[key] {
                    result[key] = aValue
                } else {
                    result[key] = bObject[key]
                }
            }

            return .object(result)
        }

        return b

    case .array(let aArray):
        if case .array(let bArray) = b {
            return .array(removeDuplicates(aArray + bArray))
        }

        return b

    default:
        return b
    }
}

func removeDuplicates(_ values: [JSONValue]) -> [JSONValue] {
    var seen = Set<String>()
    var result: [JSONValue] = []

    for value in values {
        let key = canonical(value)
        if !seen.contains(key) {
            seen.insert(key)
            result.append(value)
        }
    }

    return result
}

func canonical(_ value: JSONValue) -> String {
    switch value {
    case .string(let s):
        return "s:" + jsonEscape(s)

    case .number(let n):
        if let d = Double(n) {
            return "n:" + String(describing: d)
        }
        return "n:invalid"

    case .bool(let b):
        return "b:" + (b ? "true" : "false")

    case .null:
        return "null"

    case .array(let arr):
        return "a[" + arr.map { canonical($0) }.joined(separator: ",") + "]"

    case .object(let obj):
        let keys = Array(obj.keys).sorted()
        let parts = keys.map { key in
            "\"" + jsonEscape(key) + "\": " + canonical(obj[key]!)
        }
        return "o{" + parts.joined(separator: ",") + "}"
    }
}

func jsonEscape(_ s: String) -> String {
    var out = [String]()

    for c in s {
        switch c {
        case "\"" :
            out.append("\\\"")
        case "\\" :
            out.append("\\\\")
        case "\n":
            out.append("\\n")
        case "\r":
            out.append("\\r")
        case "\t":
            out.append("\\t")
        case "\u{0008}":
            out.append("\\b")
        case "\u{000C}":
            out.append("\\f")
        default:
            if c.isControlCharacter {
                if let ascii = c.asciiValue {
                    out.append("\\u")
                    out.append(String(format: "%04x", UInt32(ascii)))
                } else if let first = c.unicodeScalars.first {
                    out.append("\\u")
                    out.append(String(format: "%04x", first.scalarValue))
                } else {
                    out.append(c)
                }
            } else {
                out.append(c)
            }
        }
    }

    return out.joined()
}

func render(_ value: JSONValue, indent: Int) -> String {
    let pad = String(repeating: " ", count: indent * 2)

    switch value {
    case .string(let s):
        return "\"" + jsonEscape(s) + "\""

    case .number(let n):
        return n

    case .bool(let b):
        return b ? "true" : "false"

    case .null:
        return "null"

    case .array(let arr):
        if arr.isEmpty {
            return "[]"
        }

        let items = arr.map { render($0, indent: indent + 1) }
        return "[\n" + items.joined(separator: "\n") + "\n" + pad + "]"

    case .object(let obj):
        if obj.isEmpty {
            return "{}"
        }

        let keys = Array(obj.keys).sorted()
        let lines = keys.map { key in
            let val = obj[key]!
            "  \"\(jsonEscape(key))\": \(render(val, indent: indent + 1))"
        }

        return "{\n" + lines.joined(separator: "\n") + "\n" + pad + "}"
    }
}

