use std::collections::BTreeMap;
use std::fs;

const A_PATH: &str = "/tmp/…/config_a.json";
const B_PATH: &str = "/tmp/…/config_b.json";

#[derive(Clone)]
enum Value {
    Null,
    Bool(bool),
    Str(String),
    Num(String),
    Arr(Vec<Value>),
    Obj(BTreeMap<String, Value>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            chars: input.chars().collect(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.chars.len() {
            match self.chars[self.pos] {
                ' ' | '\t' | '\n' | '\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn expect(&mut self, expected: char) -> Result<(), String> {
        self.skip_ws();
        if self.pos < self.chars.len() && self.chars[self.pos] == expected {
            self.pos += 1;
            Ok(())
        } else {
            Err(format!("expected '{}'", expected))
        }
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Ok(Value::Str(self.parse_string()?)),
            Some('t') => self.parse_literal("true", Value::Bool(true)),
            Some('f') => self.parse_literal("false", Value::Bool(false)),
            Some('n') => self.parse_literal("null", Value::Null),
            Some(c) if c == '-' || c.is_ascii_digit() => self.parse_number(),
            None => Err("unexpected end of input".into()),
            Some(c) => Err(format!("unexpected character {}", c)),
        }
    }

    fn parse_literal(&mut self, literal: &str, value: Value) -> Result<Value, String> {
        for expected in literal.chars() {
            if self.pos >= self.chars.len() || self.chars[self.pos] != expected {
                return Err("invalid literal".into());
            }
            self.pos += 1;
        }
        Ok(value)
    }

    fn parse_object(&mut self) -> Result<Value, String> {
        self.expect('{')?;
        self.skip_ws();

        if self.peek() == Some('}') {
            self.pos += 1;
            return Ok(Value::Obj(BTreeMap::new()));
        }

        let mut map = BTreeMap::new();

        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            self.expect(':')?;
            self.skip_ws();

            let value = self.parse_value()?;
            map.insert(key, value);

            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.pos += 1;
                }
                Some('}') => {
                    self.pos += 1;
                    break;
                }
                _ => return Err("expected ',' or '}' in object".into()),
            }
        }

        Ok(Value::Obj(map))
    }

    fn parse_array(&mut self) -> Result<Value, String> {
        self.expect('[');
        self.skip_ws();

        if self.peek() == Some(']') {
            self.pos += 1;
            return Ok(Value::Arr(Vec::new()));
        }

        let mut arr = Vec::new();

        loop {
            self.skip_ws();
            arr.push(self.parse_value()?);

            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.pos += 1;
                }
                Some(']') => {
                    self.pos += 1;
                    break;
                }
                _ => return Err("expected ',' or ']' in array".into()),
            }
        }

        Ok(Value::Arr(arr))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect('"')?;
        let mut out = String::new();

        loop {
            if self.pos >= self.chars.len() {
                return Err("unterminated string".into());
            }

            let c = self.chars[self.pos];

            if c == '"' {
                self.pos += 1;
                return Ok(out);
            }

            if c == '\\' {
                self.pos += 1;
                if self.pos >= self.chars.len() {
                    return Err("unterminated escape sequence".into());
                }

                let esc = self.chars[self.pos];
                self.pos += 1;

                match esc {
                    '"' => out.push('"'),
                    '\\' => out.push('\\'),
                    '/' => out.push('/'),
                    'b' => out.push('\u{0008}'),
                    'f' => out.push('\u{000C}'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    't' => out.push('\t'),
                    'u' => {
                        let cp = self.parse_hex4()?;

                        if (0xD800..=0xDBFF).contains(&cp) {
                            if self.pos + 1 < self.chars.len()
                                && self.chars[self.pos] == '\\'
                                && self.chars[self.pos + 1] == 'u'
                            {
                                self.pos += 2;
                                let low = self.parse_hex4()?;
                                if (0xDC00..=0xDFFF).contains(&low) {
                                    let cp2 = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                                    out.push(
                                        char::from_u32(cp2)
                                            .ok_or_else(|| "invalid surrogate pair".to_string())?,
                                    );
                                    continue;
                                } else {
                                    return Err("invalid low surrogate".into());
                                }
                            } else {
                                return Err("invalid high surrogate".into());
                            }
                        } else if (0xDC00..=0xDFFF).contains(&cp) {
                            return Err("invalid low surrogate".into());
                        } else {
                            out.push(
                                char::from_u32(cp)
                                    .ok_or_else(|| "invalid unicode code point".to_string())?,
                            );
                        }
                    }
                    _ => return Err(format!("invalid escape character: {}", esc)),
                }
            } else if c.is_control() {
                return Err("raw control character in string".into());
            } else {
                out.push(c);
                self.pos += 1;
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        let mut value: u32 = 0;

        for _ in 0..4 {
            if self.pos >= self.chars.len() {
                return Err("invalid unicode escape".into());
            }

            let c = self.chars[self.pos];
            let digit = match c {
                '0'..='9' => c as u32 - '0' as u32,
                'a'..='f' => c as u32 - 'a' as u32 + 10,
                'A'..='F' => c as u32 - 'A' as u32 + 10,
                _ => return Err("invalid hexadecimal digit in unicode escape".into()),
            };

            self.pos += 1;
            value = value * 16 + digit;
        }

        Ok(value)
    }

    fn parse_number(&mut self) -> Result<Value, String> {
        let mut s = String::new();

        if self.peek() == Some('-') {
            s.push('-');
            self.pos += 1;
        }

        let mut int_digits = 0;
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() {
                s.push(c);
                self.pos += 1;
                int_digits += 1;
            } else {
                break;
            }
        }

        if int_digits == 0 {
            return Err("expected digit in number".into());
        }

        if self.peek() == Some('.') {
            self.pos += 1;

            let mut frac_digits = 0;
            while self.pos < self.chars.len() {
                let c = self.chars[self.pos];
                if c.is_ascii_digit() {
                    s.push(c);
                    self.pos += 1;
                    frac_digits += 1;
                } else {
                    break;
                }
            }

            if frac_digits == 0 {
                return Err("expected digit after decimal point".into());
            }
        }

        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.pos += 1;

            if self.peek() == Some('+') || self.peek() == Some('-') {
                s.push(self.chars[self.pos]);
                self.pos += 1;
            }

            let mut exp_digits = 0;
            while self.pos < self.chars.len() {
                let c = self.chars[self.pos];
                if c.is_ascii_digit() {
                    s.push(c);
                    self.pos += 1;
                    exp_digits += 1;
                } else {
                    break;
                }
            }

            if exp_digits == 0 {
                return Err("expected digit in exponent".into());
            }
        }

        Ok(Value::Num(s))
    }
}

fn parse_json(input: &str) -> Result<Value, String> {
    let mut parser = Parser::new(input);
    parser.skip_ws();

    let value = parser.parse_value()?;
    parser.skip_ws();

    if parser.pos != parser.chars.len() {
        return Err("trailing data after JSON value".into());
    }

    Ok(value)
}

#[derive(Clone)]
struct NumberParts {
    sign: i32,
    digits: String,
    exp: i64,
}

fn parse_number_parts(s: &str) -> Option<NumberParts> {
    let mut i = 0;
    let mut sign = 1i32;

    if i < s.len() && s.as_bytes()[i] == b'-' {
        sign = -1;
        i += 1;
    } else if i < s.len() && s.as_bytes()[i] == b'+' {
        i += 1;
    }

    let int_start = i;
    while i < s.len() && s.as_bytes()[i].is_ascii_digit() {
        i += 1;
    }

    let int_part = &s[int_start..i];
    if int_part.is_empty() {
        return None;
    }

    let mut frac_part = "";
    if i < s.len() && s.as_bytes()[i] == b'.' {
        i += 1;

        let frac_start = i;
        while i < s.len() && s.as_bytes()[i].is_ascii_digit() {
            i += 1;
        }

        frac_part = &s[frac_start..i];
        if frac_part.is_empty() {
            return None;
        }
    }

    let mut exp = 0i64;
    if i < s.len() && (s.as_bytes()[i] == b'e' || s.as_bytes()[i] == b'E') {
        i += 1;

        let exp_sign = 1i64;
        if i < s.len() && (s.as_bytes()[i] == b'+' || s.as_bytes()[i] == b'-') {
            if s.as_bytes()[i] == b'-' {
                exp_sign = -1;
            }
            i += 1;
        }

        let exp_start = i;
        while i < s.len() && s.as_bytes()[i].is_ascii_digit() {
            i += 1;
        }

        if i == exp_start {
            return None;
        }

        let exp_digits = &s[exp_start..i];
        exp = parse_i64_saturated(exp_digits) * exp_sign;
    }

    if i != s.len() {
        return None;
    }

    let digits = format!("{}{}", int_part, frac_part);

    if let Some(first_nonzero) = digits.find(|c: char| c.is_ascii_digit() && c != '0') {
        let mut d = digits[first_nonzero..].to_string();
        let mut e = exp.saturating_sub(frac_part.len() as i64);

        while d.ends_with('0') {
            d.pop();
            e = e.saturating_add(1);
        }

        Some(NumberParts { sign, digits: d, exp: e })
    } else {
        Some(NumberParts {
            sign: 1,
            digits: "0".to_string(),
            exp: 0,
        })
    }
}

fn parse_i64_saturated(s: &str) -> i64 {
    let mut value: i64 = 0;

    for c in s.bytes() {
        let digit = (c - b'0') as i64;

        if value > (i64::MAX - digit) / 10 {
            return i64::MAX;
        }

        value = value * 10 + digit;
    }

    value
}

fn number_parts_equal(a: &NumberParts, b: &NumberParts) -> bool {
    if a.digits == "0" && b.digits == "0" {
        return true;
    }

    if a.sign != b.sign {
        return false;
    }

    if a.digits == b.digits && a.exp == b.exp {
        return true;
    }

    let la: i128 = a.digits.len() as i128 + a.exp as i128;
    let lb: i128 = b.digits.len() as i128 + b.exp as i128;

    if la != lb {
        return false;
    }

    let min_exp = a.exp.min(b.exp);

    let mut da = a.digits.clone();
    let mut db = b.digits.clone();

    if a.exp > min_exp {
        let diff = (a.exp.saturating_sub(min_exp)) as usize;
        da.push_str(&"0".repeat(diff));
    }

    if b.exp > min_exp {
        let diff = (b.exp.saturating_sub(min_exp)) as usize;
        db.push_str(&"0".repeat(diff));
    }

    da == db
}

fn numbers_equal(a: &str, b: &str) -> bool {
    match (parse_number_parts(a), parse_number_parts(b)) {
        (Some(x), Some(y)) => number_parts_equal(&x, &y),
        _ => a == b,
    }
}

fn merge_values(a: &Value, b: &Value) -> Value {
    match (a, b) {
        (Value::Obj(map_a), Value::Obj(map_b)) => {
            let mut result = BTreeMap::new();

            for (k, v) in map_a {
                result.insert(k.clone(), v.clone());
            }

            for (k, v) in map_b {
                if let Some(existing) = result.get(&k) {
                    result.insert(k.clone(), merge_values(existing, v).clone());
                } else {
                    result.insert(k.clone(), v.clone());
                }
            }

            Value::Obj(result)
        }

        (Value::Arr(a_arr), Value::Arr(b_arr)) => {
            let mut result = Vec::with_capacity(a_arr.len() + b_arr.len());

            for item in a_arr.iter().chain(b_arr.iter()) {
                if !result.iter().any(|existing| values_equal(existing, item)) {
                    result.push(item.clone());
                }
            }

            Value::Arr(result)
        }

        _ => b.clone(),
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Num(x), Value::Num(y)) => numbers_equal(x, y),
        (Value::Arr(x), Value::Arr(y)) => {
            x.iter().zip(y.iter()).all(|(l, r)| values_equal(l, r))
        }
        (Value::Obj(x), Value::Obj(y)) => {
            if x.len() != y.len() {
                return false;
            }

            x.iter().all(|(k, v)| {
                let bv = y.get(k);
                bv.map(|bv| values_equal(v, bv)).unwrap_or(false)
            })
        }
        _ => false,
    }
}

fn write_value(out: &mut String, value: &Value, indent: usize) {
    match value {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => {
            if *b {
                out.push_str("true");
            } else {
                out.push_str("false");
            }
        }
        Value::Str(s) => write_string(out, s),
        Value::Num(s) => out.push_str(s),
        Value::Arr(arr) => write_array(out, arr, indent),
        Value::Obj(map) => write_object(out, map, indent),
    }
}

fn write_array(out: &mut String, arr: &[Value], indent: usize) {
    out.push('[');

    if arr.is_empty() {
        out.push(']');
        return;
    }

    out.push('\n');

    for (i, value) in arr.iter().enumerate() {
        write_indent(out, indent + 1);
        write_value(out, value, indent + 1);

        if i + 1 != arr.len() {
            out.push(',');
        }

        out.push('\n');
    }

    write_indent(out, indent);
    out.push(']');
}

fn write_object(out: &mut String, map: &BTreeMap<String, Value>, indent: usize) {
    out.push('{');

    if map.is_empty() {
        out.push('}');
        return;
    }

    out.push('\n');

    for (i, (k, v)) in map.iter().enumerate() {
        write_indent(out, indent + 1);
        write_string(out, k);
        out.push_str(": ");
        write_value(out, v, indent + 1);

        if i + 1 != map.len() {
            out.push(',');
        }

        out.push('\n');
    }

    write_indent(out, indent);
    out.push('}');
}

fn write_indent(out: &mut String, indent: usize) {
    for _ in 0..indent {
        out.push('  ');
    }
}

fn write_string(out: &mut String, s: &str) {
    out.push('"');

    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }

    out.push('"');
}

fn main() {
    let a_text = fs::read_to_string(A_PATH).unwrap_or_else(|e| {
        panic!("failed to read {}: {}", A_PATH, e);
    });

    let b_text = fs::read_to_string(B_PATH).unwrap_or_else(|e| {
        panic!("failed to read {}: {}", B_PATH, e);
    });

    let a = parse_json(&a_text).unwrap_or_else(|e| {
        panic!("failed to parse {}: {}", A_PATH, e);
    });

    let b = parse_json(&b_text).unwrap_or_else(|e| {
        panic!("failed to parse {}: {}", B_PATH, e);
    });

    let merged = merge_values(&a, &b);

    let mut output = String::new();
    write_value(&mut output, &merged, 0);
    output.push('\n');

    print!("{}", output);
}

