static char *read_file(const char *path, size_t *out_len) {
 FILE *f = fopen(path, "rb");
 if (!f) { fprintf(stderr, "Cannot open file: %s\n", path); exit(EXIT_FAILURE); }
 size_t cap = 1 << 16, len = 0;
 char *buf = xmalloc(cap);
