   if (len + 1 >= cap) {
     if (cap > SIZE_MAX / 2) { fprintf(stderr,...); exit; }
     cap *= 2;
     buf = xrealloc(buf, cap);
   }
   buf[len++] = (char)ch;
 }
 if (ferror(f)) { fprintf(stderr, "Error reading file: %s\n", path); exit; }
 buf[len] = '\0';
 fclose(f);
 *out_len = len;
 return buf;
}
