  const edges: { from: string; to: string; weight: number }[] = data.edges ?? [];

  const adjacency = new Map<string, Edge[]>();

  for (const node of nodes) {
    adjacency.set(node, []);
  }

  for (const edge of edges) {
    if (!adjacency.has(edge.from)) {
      adjacency.set(edge.from, []);
    }
    if (!adjacency.has(edge.to)) {
      adjacency.set(edge.to, []);
    }

    adjacency.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
    adjacency.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
  }

  const start = "A";

  const distances = new Map<string, number>();
  for (const node of adjacency.keys()) {
    distances.set(node, Infinity);
  }
  distances.set(start, 0);

  const heap: QueueItem[] = [{ node: start, dist: 0 }];

  const heapPush = (item: QueueItem): void => {
    heap.push(item);
    let index = heap.length - 1;

    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (heap[parent].dist <= heap[index].dist) {
        break;
      }

      const temp = heap[parent];
      heap[parent] = heap[index];
      heap[index] = temp;
      index = parent;
    }
  };

  const heapPop = (): QueueItem | undefined => {
    if (heap.length === 0) {
      return undefined;
    }

    const result = heap[0];
    const last = heap.pop()!;

    if (heap.length > 0) {
      heap[0] = last;
      let index = 0;

      while (true) {
        const left = index * 2 + 1;
        const right = left + 1;
        let smallest = index;

        if (left < heap.length && heap[left].dist < heap[smallest].dist) {
          smallest = left;
        }

        if (right < heap.length && heap[right].dist < heap[smallest].dist) {
          smallest = right;
        }

        if (smallest === index) {
          break;
        }

        const temp = heap[smallest];
        heap[smallest] = heap[index];
        heap[index] = temp;
        index = smallest;
      }
    }

    return result;
  };

  while (heap.length > 0) {
    const current = heapPop();
    if (!current) {
      break;
    }

    const currentDist = current.dist;
    const knownDist = distances.get(current.node);

    if (knownDist !== undefined && currentDist > knownDist) {
      continue;
    }

    const neighbors = adjacency.get(current.node);
    if (!neighbors) {
      continue;
    }

    for (const edge of neighbors) {
      const nextDist = currentDist + edge.weight;
      const oldDist = distances.get(edge.to);

      if (oldDist === undefined || nextDist < oldDist) {
        distances.set(edge.to, nextDist);
        heapPush({ node: edge.to, dist: nextDist });
      }
    }
  }

  const sortedNodes = Array.from(distances.keys()).sort();

  const output: string[] = ["=== Shortest Paths from A ===", ""];

