                    .append(product.price.setScale(2, RoundingMode.HALF_UP).toPlainString())
                    .append('\n');
        }

        output.append('\n');
        output.append("Count: ").append(filtered.size()).append('\n');

        BigDecimal total = BigDecimal.ZERO;
        for (Product product : filtered) {
            total = total.add(product.price);
        }

        output.append("Total: $").append(total.setScale(2, RoundingMode.HALF_UP).toPlainString()).append('\n');

        System.out.print(output.toString());
    }

    private static String fetch(String url) throws Exception {
        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
        connection.setRequestMethod("GET");
        connection.setConnectTimeout(10000);
        connection.setReadTimeout(10000);
        connection.setDoInput(true);
        connection.setDoOutput(false);
        connection.setRequestProperty("Accept", "application/json");

        int status = connection.getResponseCode();
        InputStream stream;

        if (status == HTTPURLConnection.HTTP_200_OK) {
            stream = connection.getInputStream();
        } else {
            stream = connection.getErrorStream();
            if (stream == null) {
                throw new RuntimeException("Server returned HTTP status " + status);
            }
        }

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        byte[] buffer = new byte[8192];
        int read;

        while ((read = stream.read(buffer)) != -1) {
            bytes.write(buffer, 0, read);
        }

        stream.close();
        connection.disconnect();

        return new String(bytes.toByteArray(), "UTF-8");
    }

    private static List<Map<?, ?>> parseArray(String json) {
        if (json == null || json.trim().isEmpty()) {
            return Collections.emptyList();
        }

        JsonParser parser = new JsonParser(json);
        List<Object> root = parser.parseArray();

        List<Map<?, ?>> result = new ArrayList<>();
        for (Object object : root) {
            if (object instanceof Map) {
                result.add((Map<?, ?>) object);
            }
        }

        return result;
    }

    private static BigDecimal toBigDecimal(Object value) {
        if (value == null) {
            return null;
        }

        if (value instanceof BigDecimal) {
            return (BigDecimal) value;
        }

        if (value instanceof Number) {
            return new BigDecimal(value.toString());
        }

        if (value instanceof String) {
            try {
                return new BigDecimal((String) value);
            } catch (Exception e) {
                return null;
            }
        }

        return null;
    }

    private static class JsonParser {
        private final String text;
        private int pos;

        JsonParser(String text) {
            this.text = text;
            this.pos = 0;
        }

        private void skipWhitespace() {
            while (pos < text.length()) {
                char c = text.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                    pos++;
                } else {
                    break;
                }
            }
        }

        private char peek() {
            return pos < text.length() ? text.charAt(pos) : '\0';
        }

        private void expect(char expected) {
            skipWhitespace();
            if (pos >= text.length() || text.charAt(pos) != expected) {
                throw new RuntimeException("Unexpected character at position " + pos);
            }
            pos++;
        }

        private boolean isDigit(char c) {
            return c >= '0' && c <= '9';
        }

        List<Object> parseArray() {
            expect('[');
            List<Object> list = new ArrayList<>();

            skipWhitespace();
            if (peek() == ']') {
                pos++;
                return list;
            }

            while (true) {
                list.add(parseValue());
                skipWhitespace();

                if (peek() == ',') {
                    pos++;
                    continue;
                }

                if (peek() == ']') {
                    pos++;
                    return list;
                }

                throw new RuntimeException("Unexpected character in array at position " + pos);
            }
        }

        Map<String, Object> parseObject() {
            expect('{');
            Map<String, Object> map = new LinkedHashMap<>();

            skipWhitespace();
            if (peek() == '}') {
                pos++;
                return map;
            }

            while (true) {
                skipWhitespace();
                String key = parseString();

                skipWhitespace();
                expect(':');
                skipWhitespace();

                map.put(key, parseValue());

                skipWhitespace();

                if (peek() == ',') {
                    pos++;
                    continue;
                }

                if (peek() == '}') {
                    pos++;
                    return map;
                }

                throw new RuntimeException("Unexpected character in object at position " + pos);
            }
        }

        String parseString() {
            expect('"');
            StringBuilder builder = new StringBuilder();

            while (true) {
                if (pos >= text.length()) {
                    throw new RuntimeException("Unterminated string");
                }

                char c = text.charAt(pos++);

                if (c == '"') {
                    return builder.toString();
                }

                if (c == '\\') {
                    if (pos >= text.length()) {
                        throw new RuntimeException("Unterminated escape sequence");
                    }

                    char escape = text.charAt(pos++);

                    switch (escape) {
                        case 'n':
                            builder.append('\n');
                            break;
                        case 't':
                            builder.append('\t');
                            break;
                        case 'r':
                            builder.append('\r');
                            break;
                        case 'b':
                            builder.append('\b');
                            break;
                        case 'f':
                            builder.append('\f');
                            break;
                        case '/':
                            builder.append('/');
                            break;
                        case '\\':
                            builder.append('\\');
                            break;
                        case '"':
                            builder.append('"');
                            break;
                        case 'u':
                            appendUnicodeEscape(builder);
                            break;
                        default:
                            builder.append(escape);
                            break;
                    }
                } else {
                    builder.append(c);
                }
            }
        }

        private void appendUnicodeEscape(StringBuilder builder) {
            int code = 0;
            boolean valid = true;

            for (int i = 0; i < 4; i++) {
                if (pos >= text.length()) {
                    valid = false;
                    break;
                }

                int value = hexValue(text.charAt(pos++));
                if (value < 0) {
                    valid = false;
                    break;
                }

                code = (code << 4) | value;
            }

            if (!valid) {
                builder.append('\ufffd');
                return;
            }

            if (code >= 0xD800 && code <= 0xDBFF) {
                int low = 0;
                boolean lowValid = true;

                if (pos + 1 < text.length() && text.charAt(pos) == '\\' && text.charAt(pos + 1) == 'u') {
                    pos += 2;

                    for (int i = 0; i < 4; i++) {
                        if (pos >= text.length()) {
                            lowValid = false;
                            break;
                        }

                        int value = hexValue(text.charAt(pos++));
                        if (value < 0) {
                            lowValid = false;
                            break;
                        }

                        low = (low << 4) | value;
                    }
                }

                if (lowValid && low >= 0xDC00 && low <= 0xDFFF) {
                    code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                } else {
                    code = 0xFFFD;
                }
            }

            if (code <= 0x10FFFF && !(code >= 0xD800 && code <= 0xDFFF)) {
                builder.appendCodePoint(code);
            } else {
                builder.append('\ufffd');
            }
        }

        private int hexValue(char c) {
            if (c >= '0' && c <= '9') {
                return c - '0';
            }
            if (c >= 'a' && c <= 'f') {
                return c - 'a' + 10;
            }
            if (c >= 'A' && c <= 'F') {
                return c - 'A' + 10;
            }
            return -1;
        }

        BigDecimal parseNumber() {
            skipWhitespace();
            int start = pos;

            if (peek() == '-') {
                pos++;
            }

            if (pos >= text.length() || !isDigit(text.charAt(pos))) {
                throw new RuntimeException("Invalid number at position " + start);
            }

            while (pos < text.length() && isDigit(text.charAt(pos))) {
                pos++;
            }

            if (peek() == '.') {
                pos++;
                while (pos < text.length() && isDigit(text.charAt(pos))) {
                    pos++;
                }
            }

            if (peek() == 'e' || peek() == 'E') {
                pos++;

                if (peek() == '+' || peek() == '-') {
                    pos++;
                }

                while (pos < text.length() && isDigit(text.charAt(pos))) {
                    pos++;
                }
            }

            return new BigDecimal(text.substring(start, pos));
        }

        Object parseValue() {
            skipWhitespace();
            char c = peek();

            if (c == '{') {
                return parseObject();
            }

            if (c == '[') {
                return parseArray();
            }

            if (c == '"') {
                return parseString();
            }

            if (c == 't') {
                if (text.startsWith("true", pos)) {
                    pos += 4;
                    return Boolean.TRUE;
                }
                throw new RuntimeException("Unexpected value at position " + pos);
            }

            if (c == 'f') {
                if (text.startsWith("false", pos)) {
                    pos += 5;
                    return Boolean.FALSE;
                }
                throw new RuntimeException("Unexpected value at position " + pos);
            }

            if (c == 'n') {
                if (text.startsWith("null", pos)) {
                    pos += 4;
                    return null;
                }
                throw new RuntimeException("Unexpected value at position " + pos);
            }

            if (c == '-' || c == '+' || isDigit(c)) {
                return parseNumber();
            }

            throw new RuntimeException("Unexpected value at position " + pos);
        }
    }
}

import java.io.*;
