use std::collections::BTreeMap;
use std::fs;

const CSV_PATH: &str = "/tmp/…/employees.csv";

fn parse_csv(content: &str) -> Vec<Vec<String>> {
    let chars: Vec<char> = content.chars().collect();
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut record: Vec<String> = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if in_quotes {
            if c == '"' {
                if i + 1 < chars.len() && chars[i + 1] == '"' {
                    field.push('"');
                    i += 2;
                } else {
                    in_quotes = false;
                    i += 1;
                }
            } else {
                field.push(c);
                i += 1;
            }
        } else {
            if c == '"' {
                in_quotes = true;
                i += 1;
            } else if c == ',' {
                record.push(field.clone());
                field.clear();
                i += 1;
            } else if c == '\n' {
                record.push(field.clone());
                field.clear();
                records.push(record);
                record = Vec::new();
                i += 1;
            } else if c == '\r' {
                if i + 1 < chars.len() && chars[i + 1] == '\n' {
                    i += 2;
                } else {
                    i += 1;
                }
                record.push(field.clone());
                field.clear();
                records.push(record);
                record = Vec::new();
            } else {
                field.push(c);
                i += 1;
            }
        }
    }

    if !field.is_empty() || !record.is_empty() {
        record.push(field.clone());
        records.push(record);
    }

    let mut filtered = Vec::new();
    for row in records {
        if !(row.len() == 1 && row[0].is_empty()) {
            filtered.push(row);
        }
    }
    filtered
}

fn main() {
    let raw = fs::read_to_string(CSV_PATH).unwrap();
    let content = raw.strip_prefix('\u{feff}').unwrap_or(&raw);
    let records = parse_csv(content);

    println!("=== Salary Report ===");
    println!();

    if records.is_empty() {
        println!("Average Salary by Department:");
        println!();
        println!("Highest Paid: N/A ($0)");
        println!();
        println!("Departments with >2 employees:");
        println!();
        println!("Total Budget: $0");
        return;
    }

    let header = &records[0];
    let header_norm: Vec<String> = header
        .iter()
        .map(|h| h.trim().to_lowercase())
        .collect();

    let col_index = |name: &str| {
        let lowered = name.to_lowercase();
        header_norm.iter().position(|h| h == lowered)
    };

    let name_idx = col_index("name").unwrap_or(1);
    let dept_idx = col_index("department").unwrap_or(2);
    let salary_idx = col_index("salary").unwrap_or(3);

    let mut stats: BTreeMap<String, (usize, f64)> = BTreeMap::new();
    let mut highest_name = String::new();
    let mut highest_salary = f64::NEG_INFINITY;
    let mut total_salary = 0.0;
    let mut has_employees = false;

    for row in &records[1..] {
        if row.len() <= name_idx
            || row.len() <= dept_idx
            || row.len() <= salary_idx
        {
            continue;
        }

        let name = row[name_idx].trim();
        let department = row[dept_idx].trim();
        let salary_text = row[salary_idx]
            .trim()
            .trim_start_matches('$')
            .trim()
            .replace(',', "");

        let Ok(salary) = salary_text.parse::<f64>() else {
            continue;
        };

        if name.is_empty() && department.is_empty() {
            continue;
        }

        has_employees = true;

        let entry = stats.entry(department.to_owned()).or_insert((0, 0.0));
        entry.0 += 1;
        entry.1 += salary;
        total_salary += salary;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    println!("Average Salary by Department:");
    for (department, (count, sum)) in &stats {
        let average = sum / count as f64;
        println!("  Department: ${:,.2}", average);
    }
    println!();

    if has_employees {
        println!("Highest Paid: {} (${:,.0})", highest_name, highest_salary);
    } else {
        println!("Highest Paid: N/A ($0)");
    }
    println!();

    println!("Departments with >2 employees:");
    for (department, (count, _)) in &stats {
        if count > 2 {
            println!("  {} ({} employees)", department, count);
        }
    }
    println!();

    println!("Total Budget: ${:,.0}", total_salary);
}

use std::collections::BTreeMap;
use std::fs;

const CSV_PATH: &str = "/tmp/…/employees.csv";

fn parse_csv(content: &str) -> Vec<Vec<String>> {
    let chars: Vec<char> = content.chars().collect();
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut record: Vec<String> = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if in_quotes {
            if c == '"' {
                if i + 1 < chars.len() && chars[i + 1] == '"' {
                    field.push('"');
                    i += 2;
                } else {
                    in_quotes = false;
                    i += 1;
                }
            } else {
                field.push(c);
                i += 1;
            }
        } else {
            if c == '"' {
                in_quotes = true;
                i += 1;
            } else if c == ',' {
                record.push(field.clone());
                field.clear();
                i += 1;
            } else if c == '\n' {
                record.push(field.clone());
                field.clear();
                records.push(record);
                record = Vec::new();
                i += 1;
            } else if c == '\r' {
                if i + 1 < chars.len() && chars[i + 1] == '\n' {
                    i += 2;
                } else {
                    i += 1;
                }
                record.push(field.clone());
                field.clear();
                records.push(record);
                record = Vec::new();
            } else {
                field.push(c);
                i += 1;
            }
        }
    }

    if !field.is_empty() || !record.is_empty() {
        record.push(field.clone());
        records.push(record);
    }

    let mut filtered = Vec::new();
    for row in records {
        if !(row.len() == 1 && row[0].is_empty()) {
            filtered.push(row);
        }
    }
    filtered
}

fn insert_commas(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut start = 0;

    if let Some(first) = chars.first() {
        if !first.is_ascii_digit() {
            start = 1;
        }
    }

    let mut result = String::new();
    for (idx, &c) in chars.iter().enumerate() {
        if start > 0
            && c.is_ascii_digit()
            && (idx - start + 1) % 3 == 0
            && idx + 1 < chars.len()
        {
            result.push(',');
        }
        result.push(c);
    }

    result
}

fn format_number(value: f64, decimals: usize) -> String {
    let formatted = format!("{:.*}", decimals, value);

    if let Some((int_part, frac_part)) = formatted.split_once('.') {
        let mut result = insert_commas(int_part);
        result.push('.');
        result.push_str(frac_part);
        result
    } else {
        insert_commas(formatted)
    }
}

fn main() {
    let raw = fs::read_to_string(CSV_PATH).unwrap();

    let content = match raw.strip_prefix('\u{feff}') {
        Some(s) => s,
        None => raw.as_str(),
    };

    let records = parse_csv(content);

    println!("=== Salary Report ===");
    println!();

    if records.is_empty() {
        println!("Average Salary by Department:");
        println!();
        println!("Highest Paid: N/A ($0)");
        println!();
        println!("Departments with >2 employees:");
        println!();
        println!("Total Budget: ${}", format_number(0.0, 0));
        return;
    }

    let header = &records[0];
    let header_norm: Vec<String> = header
        .iter()
        .map(|h| h.trim().to_lowercase())
        .collect();

    let col_index = |name: &str| {
        let lowered = name.to_lowercase();
        header_norm.iter().position(|h| h.as_str() == lowered.as_str())
    };

    let name_idx = col_index("name").unwrap_or(1);
    let dept_idx = col_index("department").unwrap_or(2);
    let salary_idx = col_index("salary").unwrap_or(3);

    let mut stats: BTreeMap<String, (usize, f64)> = BTreeMap::new();
    let mut highest_name = String::new();
    let mut highest_salary = f64::NEG_INFINITY;
    let mut total_salary = 0.0;
    let mut has_employees = false;

    for row in &records[1..] {
        if row.len() <= name_idx
            || row.len() <= dept_idx
            || row.len() <= salary_idx
        {
            continue;
        }

        let name = row[name_idx].trim();
        let department = row[dept_idx].trim();
        let salary_text = row[salary_idx]
            .trim()
            .replace('$', "")
            .trim()
            .replace(',', "");

        let salary = match salary_text.parse::<f64>() {
            Ok(v) => v,
            Err(_) => continue,
        };

        if name.is_empty() && department.is_empty() {
            continue;
        }

        has_employees = true;

        let entry = stats.entry(department.to_owned()).or_insert((0, 0.0));
        entry.0 += 1;
        entry.1 += salary;
        total_salary += salary;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name.to_owned();
        }
    }

    println!("Average Salary by Department:");
    for (department, (count, sum)) in &stats {
        let average = (*sum) / (*count) as f64;
        println!("  Department: ${}", format_number(average, 2));
    }
    println!();

    if has_employees {
        println!(
            "Highest Paid: {} (${})",
            highest_name,
            format_number(highest_salary, 0)
        );
    } else {
        println!("Highest Paid: N/A ($0)");
    }
    println!();

    println!("Departments with >2 employees:");
    for (department, (count, _)) in &stats {
        if *count > 2 {
            println!("  {} ({} employees)", department, count);
        }
    }
    println!();

    println!("Total Budget: ${}", format_number(total_salary, 0));
}

import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    private static final String DEFAULT_A = "/tmp/…/config_a.json";
    private static final String DEFAULT_B = "/tmp/…/config_b.json";

    private static final int TYPE_STRING = 0;
    private static final int TYPE_NUMBER = 1;
    private static final int TYPE_BOOLEAN = 2;
    private static final int TYPE_NULL = 3;

    public static void main(String[] args) throws Exception {
        String pathA = DEFAULT_A;
        String pathB = DEFAULT_B;
        if (args.length > 0) {
            pathA = args[0];
        }
        if (args.length > 1) {
            pathB = args[1];
        }

        JsonNode a = readJson(pathA);
        JsonNode b = readJson(pathB);
        JsonNode merged = merge(a, b);
        System.out.println(toJson(merged, 0));
    }

    private static JsonNode readJson(String path) throws Exception {
        String text = new String(Files.readAllBytes(Paths.get(path)), StandardCharsets.UTF_8);
        if (text.startsWith("\uFEFF")) {
            text = text.substring(1);
        }
        return parseJson(text);
    }

    private static JsonNode parseJson(String text) {
        JsonParser parser = new JsonParser(text);
        JsonNode root = parser.parseValue();
        parser.skipWhitespace();
        if (!parser.atEof()) {
            throw new JsonParseException("Unexpected content after JSON value");
        }
        return root;
    }

    private static JsonNode merge(JsonNode a, JsonNode b) {
        if (a == null) {
            return b;
        }
        if (b == null) {
            return a;
        }

        if (a.isObject() && b.isObject()) {
            Map<String, JsonNode> ma = a.getMap();
            Map<String, JsonNode> mb = b.getMap();
            Map<String, JsonNode> result = new LinkedHashMap<>();
            Set<String> keys = new TreeSet<>();
            keys.addAll(ma.keySet());
            keys.addAll(mb.keySet());

            for (String key : keys) {
                JsonNode av = ma.get(key);
                JsonNode bv = mb.get(key);

                if (av != null && bv != null) {
                    if (av.isObject() && bv.isObject()) {
                        result.put(key, merge(av, bv));
                    } else if (av.isArray() && bv.isArray()) {
                        result.put(key, concat(av, bv));
                    } else {
                        result.put(key, bv);
                    }
                } else if (av != null) {
                    result.put(key, av);
                } else {
                    result.put(key, bv);
                }
            }
            return new ObjectNode(result);
        }

        if (a.isArray() && b.isArray()) {
            return concat(a, b);
        }

        return b;
    }

    private static JsonNode concat(JsonNode a, JsonNode b) {
        List<JsonNode> all = new ArrayList<>();
        all.addAll(a.getList());
        all.addAll(b.getList());

        List<JsonNode> result = new ArrayList<>();
        Set<JsonNode> seen = new HashSet<>();
        for (JsonNode value : all) {
            if (seen.add(value)) {
                result.add(value);
            }
        }
        return new ArrayNode(result);
    }

    private static abstract class JsonNode {
        public abstract boolean isObject();
        public abstract boolean isArray();
        public abstract JsonNode merge(JsonNode other);
        public abstract boolean equals(Object obj);
        public abstract int hashCode();
    }

    private static class ScalarNode extends JsonNode {
        private final int type;
        private final String raw;
        private final String value;

        ScalarNode(int type, String raw, String value) {
            this.type = type;
            this.raw = raw;
            this.value = value;
        }

        @Override
        public boolean isObject() {
            return false;
        }

        @Override
        public boolean isArray() {
            return false;
        }

        @Override
        public JsonNode merge(JsonNode other) {
            return other;
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof ScalarNode)) {
                return false;
            }
            ScalarNode other = (ScalarNode) obj;
            if (type != other.type) {
                return false;
            }
            switch (type) {
                case TYPE_STRING:
                    return value != null && value.equals(other.value);
                case TYPE_NUMBER:
                    return numericEqual(raw, other.raw);
                case TYPE_BOOLEAN:
                case TYPE_NULL:
                    return raw.equals(other.raw);
                default:
                    return false;
            }
        }

        @Override
        public int hashCode() {
            switch (type) {
                case TYPE_STRING:
                    return value.hashCode();
                case TYPE_NUMBER:
                    return numericHash(raw);
                case TYPE_BOOLEAN:
                case TYPE_NULL:
                    return raw.hashCode();
                default:
                    return 0;
            }
        }

        public String asString() {
            switch (type) {
                case TYPE_STRING:
                    return quote(value);
                default:
                    return raw;
            }
        }

        private static boolean numericEqual(String a, String b) {
            try {
                return new BigDecimal(a).compareTo(new BigDecimal(b)) == 0;
            } catch (Exception e) {
                return a.equals(b);
            }
        }

        private static int numericHash(String a) {
            try {
                return new BigDecimal(a).stripTrailingZeros().toPlainString().hashCode();
            } catch (Exception e) {
                return a.hashCode();
            }
        }
    }

    private static class ObjectNode extends JsonNode {
        private final Map<String, JsonNode> map;

        ObjectNode(Map<String, JsonNode> map) {
            if (map == null) {
                this.map = new LinkedHashMap<>();
            } else {
                this.map = new LinkedHashMap<>(map);
            }
        }

        @Override
        public boolean isObject() {
            return true;
        }

        @Override
        public boolean isArray() {
            return false;
        }

        @Override
        public JsonNode merge(JsonNode other) {
            return Main.merge(this, other);
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof ObjectNode)) {
                return false;
            }
            ObjectNode other = (ObjectNode) obj;
            if (map.size() != other.map.size()) {
                return false;
            }
            for (Map.Entry<String, JsonNode> entry : map.entrySet()) {
                JsonNode value = other.map.get(entry.getKey());
                if (value == null || !entry.getValue().equals(value)) {
                    return false;
                }
            }
            return true;
        }

        @Override
        public int hashCode() {
            int h = 0;
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            for (String key : keys) {
                h = 31 * h + key.hashCode();
                h = 31 * h + map.get(key).hashCode();
            }
            return h;
        }

        public Map<String, JsonNode> getMap() {
            return Collections.unmodifiableMap(map);
        }
    }

    private static class ArrayNode extends JsonNode {
        private final List<JsonNode> list;

        ArrayNode(List<JsonNode> list) {
            if (list == null) {
                this.list = new ArrayList<>();
            } else {
                this.list = new ArrayList<>(list);
            }
        }

        @Override
        public boolean isObject() {
            return false;
        }

        @Override
        public boolean isArray() {
            return true;
        }

        @Override
        public JsonNode merge(JsonNode other) {
            return Main.merge(this, other);
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof ArrayNode)) {
                return false;
            }
            ArrayNode other = (ArrayNode) obj;
            if (list.size() != other.list.size()) {
                return false;
            }
            for (int i = 0; i < list.size(); i++) {
                if (!list.get(i).equals(other.list.get(i))) {
                    return false;
                }
            }
            return true;
        }

        @Override
        public int hashCode() {
            int h = 1;
            for (JsonNode value : list) {
                h = 31 * h + value.hashCode();
            }
            return h;
        }

        public List<JsonNode> getList() {
            return Collections.unmodifiableList(list);
        }
    }

    private static class JsonParser {
        private final String text;
        private int pos = 0;

        JsonParser(String text) {
            this.text = text;
        }

        private void skipWhitespace() {
            while (pos < text.length()) {
                char c = text.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                    pos++;
                } else {
                    break;
                }
            }
        }

        private boolean atEof() {
            return pos >= text.length();
        }

        private char peek() {
            return pos >= text.length() ? '\0' : text.charAt(pos);
        }

        private void expect(char expected) {
            skipWhitespace();
            if (pos >= text.length() || text.charAt(pos) != expected) {
                fail("Expected '" + expected + "'");
            }
            pos++;
        }

        private void fail(String message) {
            throw new JsonParseException(message + " at position " + pos + " in input");
        }

        JsonNode parseValue() {
            skipWhitespace();
            char c = peek();
            switch (c) {
                case '{':
                    return parseObject();
                case '[':
                    return parseArray();
                case '"':
                    return parseString();
                case 't':
                    return parseLiteral("true", TYPE_BOOLEAN);
                case 'f':
                    return parseLiteral("false", TYPE_BOOLEAN);
                case 'n':
                    return parseLiteral("null", TYPE_NULL);
                default:
                    return parseNumber();
            }
        }

        private ScalarNode parseLiteral(String literal, int type) {
            if (text.startsWith(literal, pos)) {
                pos += literal.length();
                return new ScalarNode(type, literal, null);
            }
            fail("Unexpected token, expected " + literal);
            return null;
        }

        private JsonNode parseObject() {
            expect('{');
            Map<String, JsonNode> result = new LinkedHashMap<>();
            skipWhitespace();

            if (peek() == '}') {
                pos++;
                return new ObjectNode(result);
            }

            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                expect(':');
                JsonNode value = parseValue();
                result.put(key, value);
                skipWhitespace();

                char c = peek();
                if (c == ',') {
                    pos++;
                } else if (c == '}') {
                    pos++;
                    return new ObjectNode(result);
                } else {
                    fail("Unexpected character in object");
                }
            }
        }

        private JsonNode parseArray() {
            expect('[');
            List<JsonNode> result = new ArrayList<>();
            skipWhitespace();

            if (peek() == ']') {
                pos++;
                return new ArrayNode(result);
            }

            while (true) {
                JsonNode value = parseValue();
                result.add(value);
                skipWhitespace();

                char c = peek();
                if (c == ',') {
                    pos++;
                } else if (c == ']') {
                    pos++;
                    return new ArrayNode(result);
                } else {
                    fail("Unexpected character in array");
                }
            }
        }

        private ScalarNode parseString() {
            expect('"');
            StringBuilder sb = new StringBuilder();

            while (true) {
                if (pos >= text.length()) {
                    fail("Unterminated string");
                }
                char c = text.charAt(pos++);

                if (c == '"') {
                    return new ScalarNode(TYPE_STRING, null, sb.toString());
                }

                if (c != '\\') {
                    sb.append(c);
                    continue;
                }

                if (pos >= text.length()) {
                    fail("Unterminated escape sequence");
                }
                char escape = text.charAt(pos++);
                switch (escape) {
                    case '"':
                        sb.append('"');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    case '/':
                        sb.append('/');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'u': {
                        int code = parseHex4();
                        if (code >= 0xD800 && code <= 0xDBFF
                                && pos + 1 < text.length()
                                && text.charAt(pos) == '\\'
                                && text.charAt(pos + 1) == 'u') {
                            pos += 2;
                            int low = parseHex4();
                            if (low >= 0xDC00 && low <= 0xDFFF) {
                                code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                            }
                        }
                        sb.appendCodePoint(code);
                        break;
                    }
                    default:
                        fail("Invalid string escape sequence");
                }
            }
        }

        private ScalarNode parseNumber() {
            StringBuilder sb = new StringBuilder();
            while (pos < text.length()) {
                char c = text.charAt(pos);
                if (c == ',' || c == '}' || c == ']' || c == ':'
                        || c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                    break;
                }
                sb.append(c);
                pos++;
            }

            String raw = sb.toString();
            if (raw.isEmpty()) {
                fail("Unexpected number");
            }
            try {
                new BigDecimal(raw);
            } catch (NumberFormatException e) {
                fail("Invalid number: " + raw);
            }
            return new ScalarNode(TYPE_NUMBER, raw, null);
        }

        private int parseHex4() {
            int value = 0;
            for (int i = 0; i < 4; i++) {
                if (pos >= text.length()) {
                    fail("Unterminated unicode escape");
                }
                char c = text.charAt(pos++);
                int digit;
                if (c >= '0' && c <= '9') {
                    digit = c - '0';
                } else if (c >= 'a' && c <= 'f') {
                    digit = c - 'a' + 10;
                } else if (c >= 'A' && c <= 'F') {
                    digit = c - 'A' + 10;
                } else {
                    fail("Invalid unicode escape");
                }
                value = (value << 4) | digit;
            }
            return value;
        }
    }

    private static JsonNode toJson(JsonNode node, int indent) {
        return writeNode(node, indent);
    }

    private static String writeNode(JsonNode node, int indent) {
        if (node.isArray()) {
            return writeArray(node, indent);
        }
        if (node.isObject()) {
            return writeObject(node, indent);
        }
        return ((ScalarNode) node).asString();
    }

    private static String writeObject(JsonNode node, int indent) {
        Map<String, JsonNode> map = node.getMap();
        if (map.isEmpty()) {
            return "{}";
        }

        StringBuilder sb = new StringBuilder();
        sb.append('{').append('\n');

        List<String> keys = new ArrayList<>(map.keySet());
        Collections.sort(keys);

        for (int i = 0; i < keys.size(); i++) {
            sb.append(spaces(indent + 1));
            sb.append(quote(keys.get(i)));
            sb.append(": ");
            sb.append(writeNode(map.get(keys.get(i)), indent + 1));
            if (i < keys.size() - 1) {
                sb.append(',');
            }
            sb.append('\n');
        }

        sb.append(spaces(indent)).append('}');
        return sb.toString();
    }

    private static String writeArray(JsonNode node, int indent) {
        List<JsonNode> list = node.getList();
        if (list.isEmpty()) {
            return "[]";
        }

        StringBuilder sb = new StringBuilder();
        sb.append('[').append('\n');

        for (int i = 0; i < list.size(); i++) {
            sb.append(spaces(indent + 1));
            sb.append(writeNode(list.get(i), indent + 1));
            if (i < list.size() - 1) {
                sb.append(',');
            }
            sb.append('\n');
        }

        sb.append(spaces(indent)).append(']');
        return sb.toString();
    }

    private static String spaces(int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static String quote(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        if (s == null) {
            return sb.append('"').toString();
        }

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"':
                    sb.append('\\').append('"');
                    break;
                case '\\':
                    sb.append('\\').append('\\');
                    break;
                case '\b':
                    sb.append('\\').append('b');
                    break;
                case '\f':
                    sb.append('\\').append('f');
                    break;
                case '\n':
                    sb.append('\\').append('n');
                    break;
                case '\r':
                    sb.append('\\').append('r');
                    break;
                case '\t':
                    sb.append('\\').append('t');
                    break;
                default:
                    if (c < 0x20) {
                        sb.append('\\').append('u').append(hex4(c));
                    } else if (c > 0x7E) {
                        sb.append('\\').append('u').append(hex4(c));
                    } else {
                        sb.append(c);
                    }
            }
        }

        sb.append('"');
        return sb.toString();
    }

    private static String hex4(int value) {
        String hex = Integer.toHexString(value);
        while (hex.length() < 4) {
            hex = "0" + hex;
        }
        return hex;
    }

    private static class JsonParseException extends Exception {
        JsonParseException(String message) {
            super(message);
        }
    }
