#[derive(Clone, Debug)]
enum Value {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            chars: input.chars().collect(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.chars.len() {
            match self.chars[self.pos] {
                ' ' | '\t' | '\n' | '\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn expect(&mut self, c: char) {
        if self.peek() == Some(c) {
            self.pos += 1;
        } else {
            self.pos += 1;
        }
    }

    fn parse_string(&mut self) -> String {
        self.skip_ws();
        let mut s = String::new();
        self.expect('"');

        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];

            if c == '"' {
                self.pos += 1;
                return s;
            }

            if c == '\\' {
                self.pos += 1;
                if self.pos >= self.chars.len() {
                    break;
                }

                match self.chars[self.pos] {
                    '"' => {
                        self.pos += 1;
                        s.push('"');
                    }
                    '\\' => {
                        self.pos += 1;
                        s.push('\\');
                    }
                    '/' => {
                        self.pos += 1;
                        s.push('/');
                    }
                    'b' => {
                        self.pos += 1;
                        s.push('\u{0008}');
                    }
                    'f' => {
                        self.pos += 1;
                        s.push('\u{000C}');
                    }
                    'n' => {
                        self.pos += 1;
                        s.push('\n');
                    }
                    'r' => {
                        self.pos += 1;
                        s.push('\r');
                    }
                    't' => {
                        self.pos += 1;
                        s.push('\t');
                    }
                    'u' => {
                        self.pos += 1;
                        let first = self.parse_hex4();
                        let mut code = first;

                        if (0xD800..=0xDBFF).contains(&first) {
                            if self.pos + 1 < self.chars.len()
                                && self.chars[self.pos] == '\\'
                                && self.chars[self.pos + 1] == 'u'
                            {
                                self.pos += 2;
                                let second = self.parse_hex4();
                                if (0xDC00..=0xDFFF).contains(&second) {
                                    code = 0x10000 + ((first - 0xD800) << 10) + (second - 0xDC00);
                                }
                            }
                        }

                        if let Some(ch) = char::from_u32(code) {
                            s.push(ch);
                        } else {
                            s.push('\u{FFFD}');
                        }
                    }
                    _ => {
                        self.pos += 1;
                    }
                }
                continue;
            }

            s.push(c);
            self.pos += 1;
        }

        s
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut value = 0u32;
        for _ in 0..4 {
            let c = self.peek().unwrap_or('0');
            value = value * 16 + hex_value(c);
            if self.pos < self.chars.len() {
                self.pos += 1;
            }
        }
        value
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;

        if self.peek() == Some('-') || self.peek() == Some('+') {
            self.pos += 1;
        }

        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            self.pos += 1;
        }

        if self.pos < self.chars.len() && self.chars[self.pos] == '.' {
            self.pos += 1;
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }

        if self.pos < self.chars.len()
            && (self.chars[self.pos] == 'e' || self.chars[self.pos] == 'E')
        {
            self.pos += 1;
            if self.pos < self.chars.len()
                && (self.chars[self.pos] == '+' || self.chars[self.pos] == '-')
            {
                self.pos += 1;
            }
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }

        let text: String = self.chars[start..self.pos].iter().collect();
        text.parse::<f64>().unwrap_or(0.0)
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();

        match self.peek() {
            Some('"') => Value::String(self.parse_string()),
            Some(c) if c == '-' || c == '+' || c.is_ascii_digit() => {
                Value::Number(self.parse_number())
            }
            Some('{') => Value::Object(self.parse_object()),
            Some('[') => Value::Array(self.parse_array()),
            Some('t') => {
                self.expect('t');
                self.expect('r');
                self.expect('e');
                Value::Bool(true)
            }
            Some('f') => {
                self.expect('f');
                self.expect('a');
                self.expect('l');
                Value::Bool(false)
            }
            Some('n') => {
                self.expect('n');
                self.expect('u');
                self.expect('l');
                Value::Null
            }
            _ => Value::Null,
        }
    }

    fn parse_array(&mut self) -> Vec<Value> {
        self.expect('[');
        self.skip_ws();

        if self.peek() == Some(']') {
            self.pos += 1;
            return Vec::new();
        }

        let mut items = Vec::new();

        loop {
            let value = self.parse_value();
            items.push(value);

            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.pos += 1;
                }
                Some(']') => {
                    self.pos += 1;
                    break;
                }
                _ => break,
            }
        }

        items
    }

    fn parse_object(&mut self) -> Vec<(String, Value)> {
        self.expect('{');
        self.skip_ws();

        if self.peek() == Some('}') {
            self.pos += 1;
            return Vec::new();
        }

        let mut fields = Vec::new();

        loop {
            let key = self.parse_string();
            self.skip_ws();
            self.expect(':');
            let value = self.parse_value();
            fields.push((key, value));

            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.pos += 1;
                }
                Some('}') => {
                    self.pos += 1;
                    break;
                }
                _ => break,
            }
        }

        fields
    }
}

fn hex_value(c: char) -> u32 {
    match c {
        '0'..='9' => c as u32 - '0' as u32,
        'a'..='f' => c as u32 - 'a' as u32 + 10,
        'A'..='F' => c as u32 - 'A' as u32 + 10,
        _ => 0,
    }
}

struct Product {
    name: String,
    price: f64,
}

fn fetch_body() -> Result<String, String> {
    let mut stream = TcpStream::connect(("127.0.0.1", 18923))
        .map_err(|e| format!("{}", e))?;

    let request = b"GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream
        .write_all(request)
        .map_err(|e| format!("{}", e))?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|e| format!("{}", e))?;

    Ok(response)
}

fn body_from_response(response: &str) -> &str {
    if let Some(pos) = response.find("\r\n\r\n") {
        return &response[pos + 4..];
    }

    if let Some(pos) = response.find("\n\n") {
        return &response[pos + 2..];
    }

    &response
}

fn main() {
    let response = match fetch_body() {
        Ok(response) => response,
        Err(_) => String::new(),
    };

    let body = body_from_response(&response);
    let body = body.strip_prefix('\u{FEFF}').unwrap_or(&body);

    let parser = Parser::new(body);
    let root = parser.parse_value();
    let values = match root {
        Value::Array(values) => values,
        _ => Vec::new(),
    };

    let mut products = Vec::new();

    for value in values {
        if let Value::Object(fields) = value {
            let mut name = String::new();
            let mut price = None;

            for (key, field) in fields {
                match field {
                    Value::String(value) => {
                        if key == "name" {
                            name = value;
                        } else if key == "price" {
                            if let Ok(parsed) = value.parse::<f64>() {
                                price = Some(parsed);
                            }
                        }
                    }
                    Value::Number(value) => {
                        if key == "price" {
                            price = Some(value);
                        }
                    }
                    _ => {}
                }
            }

            if let Some(price) = price {
                if price > 50.0 {
                    products.push(Product { name, price });
                }
            }
        }
    }

    products.sort_by(|a, b| a.name.cmp(&b.name));

    let total: f64 = products.iter().map(|product| product.price).sum();

    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    for product in &products {
        println!("{}: ${:.2}", product.name, product.price);
    }

    println!();
    println!("Count: {}", products.len());
    println!("Total: ${:.2}", total);
}

