        'a'..='f' => c as u32 - 'a' as u32 + 10,
        'A'..='F' => c as u32 - 'A' as u32 + 10,
        _ => 0,
    }
}

struct Product {
    name: String,
    price: f64,
}

fn fetch_body() -> Result<String, String> {
    let mut stream = TcpStream::connect(("127.0.0.1", 18923))
        .map_err(|e| format!("{}", e))?;

    let request = b"GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream
        .write_all(request)
        .map_err(|e| format!("{}", e))?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|e| format!("{}", e))?;

    Ok(response)
}

fn body_from_response(response: &str) -> &str {
    if let Some(pos) = response.find("\r\n\r\n") {
        return &response[pos + 4..];
    }

    if let Some(pos) = response.find("\n\n") {
        return &response[pos + 2..];
    }

    &response
}

fn main() {
    let response = match fetch_body() {
        Ok(response) => response,
        Err(_) => String::new(),
    };

    let body = body_from_response(&response);
    let body = body.strip_prefix('\u{FEFF}').unwrap_or(&body);

    let mut parser = Parser::new(body);
    let root = parser.parse_value();
    let values = match root {
        Value::Array(values) => values,
        _ => Vec::new(),
    };

    let mut products = Vec::new();

    for value in values {
        if let Value::Object(fields) = value {
            let mut name = String::new();
            let mut price = None;

            for (key, field) in fields {
                match field {
                    Value::String(value) => {
                        if key == "name" {
                            name = value;
                        } else if key == "price" {
                            if let Ok(parsed) = value.parse::<f64>() {
                                price = Some(parsed);
                            }
                        }
                    }
                    Value::Number(value) => {
                        if key == "price" {
                            price = Some(value);
                        }
                    }
                    _ => {}
                }
            }

            if let Some(price) = price {
                if price > 50.0 {
                    products.push(Product { name, price });
                }
            }
        }
    }

    products.sort_by(|a, b| a.name.cmp(&b.name));

    let total: f64 = products.iter().map(|product| product.price).sum();

    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    for product in &products {
        println!("{}: ${:.2}", product.name, product.price);
    }

    println!();
    println!("Count: {}", products.len());
    println!("Total: ${:.2}", total);
}

