`static int ascii_lower(char c) { if (c >= 'A' && c <= 'Z') return (char)(c + ('a' - 'A')); return c; }`

`static int ascii_ieq(char a, char b) { return ascii_lower(a) == ascii_lower(b); }`

`static int ieq_str(const char *s, const char *expected) { while (*expected != '\0') { if (*s == '\0' || !ascii_ieq(*s, *expected)) return 0; s++; expected++; } return *s == '\0'; }`

`static int ieq_at(const char *s, const char *expected, const char *end) { while (*expected != '\0') { if (s >= end) return 0; if (!ascii_ieq(*s, *expected)) return 0; s++; expected++; } return 1; }`

`static int contains_caseless(const char *hay, size_t hay_len, const char *needle) { size_t needle_len = strlen(needle); if (hay_len < needle_len) return 0; for (size_t i=0; i <= hay_len - needle_len; i++) { int ok=1; for (size_t j=0; j<needle_len; j++) { if (!ascii_ieq(hay[i+j], needle[j])) { ok=0; break; } } if (ok) return 1; } return 0; }`

`static const char *find_sub(const char *haystack, size_t haystack_len, const char *needle, size_t needle_len) { if (needle_len == 0) return haystack; if (haystack_len < needle_len) return NULL; for (size_t i=0; i <= haystack_len - needle_len; i++) { if (memcmp(haystack + i, needle, needle_len) == 0) return haystack + i; } return NULL; }`

`static int ensure_append(char **buf, size_t *len, size_t *cap, char c) { if (*len + 1 >= *cap) { size_t newcap = *cap ? *cap * 2 : 64; if (newcap < *cap) return 0; char *newbuf = realloc(*buf, newcap); if (!newbuf) return 0; *buf = newbuf; *cap = newcap; } (*buf)[(*len)++] = c; return 1; }`

