import os
import sys

PROJECT_DIR = "/tmp/…/project_tree"


def get_file_stats(path):
    total_bytes = 0
    newline_count = 0
    last_byte = None

    try:
        with open(path, "rb") as f:
            while True:
                chunk = f.read(65536)
                if not chunk:
                    break
                newline_count += chunk.count(b"\n")
                total_bytes += len(chunk)
                last_byte = chunk[-1]
    except OSError:
        return None

    if total_bytes == 0:
        return 0, 0

    if last_byte == 0x0A:
        line_count = newline_count
    else:
        line_count = newline_count + 1

    return line_count, total_bytes


def main():
    groups = {}
    total_files = 0
    total_lines = 0
    total_characters = 0

    for root, dirs, files in os.walk(PROJECT_DIR, followlinks=False):
        real_dirs = []
        for name in dirs:
            if not os.path.islink(os.path.join(root, name)):
                real_dirs.append(name)
        dirs[:] = real_dirs

        for name in files:
            file_path = os.path.join(root, name)

            if os.path.islink(file_path):
                continue

            if not os.path.isfile(file_path):
                continue

            relative_path = os.path.relpath(file_path, PROJECT_DIR).replace(os.sep, "/")
            extension = os.path.splitext(name)[1]

            stats = get_file_stats(file_path)
            if stats is None:
                continue

            lines, chars = stats
            groups.setdefault(extension, []).append((relative_path, lines, chars))

            total_files += 1
            total_lines += lines
            total_characters += chars

    output = ["=== File Tree Analysis ===", ""]

    for extension in sorted(groups):
        entries = groups[extension]
        entries.sort(key=lambda item: item[0])

        if extension:
            output.append(f"Extension: {extension}")
        else:
            output.append("Extension:")

        output.append(f"  Files: {len(entries)}")

        extension_lines = sum(item[1] for item in entries)
        extension_chars = sum(item[2] for item in entries)

        output.append(f"  Total Lines: {extension_lines}")
        output.append(f"  Total Characters: {extension_chars}")

        for relative_path, lines, chars in entries:
            output.append(f"    {relative_path}: {lines} lines, {chars} chars")

    if groups:
        output.append("")

    output.append(f"Total: {total_files} files, {total_lines} lines, {total_characters} characters")

    sys.stdout.write("\n".join(output))
    sys.stdout.write("\n")


