            if items[i].0 < items[parent].0 {
                items.swapAt(i, parent)
                i = parent
            } else {
                break
            }
        }
    }

    func pop() -> (Double, String)? {
        guard !items.isEmpty else { return nil }
        if items.count == 1 {
            return items.removeLast()
        }
        let top = items[0]
        items[0] = items.removeLast()
        var i = 0
        while true {
            let left = i * 2 + 1
            let right = left + 1
            var smallest = i
            if left < items.count && items[left].0 < items[smallest].0 {
                smallest = left
            }
            if right < items.count && items[right].0 < items[smallest].0 {
                smallest = right
            }
            if smallest == i {
                break
            }
            items.swapAt(i, smallest)
            i = smallest
        }
        return top
    }
}

func asDouble(_ value: Any?) -> Double? {
    if let d = value as? Double {
        return d
    }
    if let i = value as? Int {
        return Double(i)
    }
    if let s = value as? String {
        return Double(s)
    }
    return nil
}

func formatDistance(_ distance: Double) -> String {
    if distance == Double.infinity {
        return "Infinity"
    }
    let rounded = distance.rounded(.toInteger)
    if abs(distance - rounded) < 1e-9 {
        if let roundedInt = Int(rounded) {
            return String(roundedInt)
        }
    }
    return distance.description
}

func run() {
    let filePath = "/tmp/…/graph.json"
    guard let json = String(contentsOfFile: filePath, encoding: .utf8) else {
        return
    }

    let parser = Parser(text: json)
    guard let jsonValue = parser.parse() else {
        return
    }
    guard let jsonDict = jsonValue as? [String: Any] else {
        return
    }

    let source = "A"
    let rawNodes = jsonDict["nodes"] as? [String] ?? []
    let rawEdges = jsonDict["edges"] as? [[String: Any]] ?? []

    var nodes = rawNodes
    if !nodes.contains(source) {
        nodes.append(source)
    }

    var adjacency: [String: [(String, Double)]] = [:]
    for node in nodes {
        adjacency[node] = [:]
    }

    for edge in rawEdges {
        guard let edgeDict = edge as? [String: Any] else {
            continue
        }
        guard let from = edgeDict["from"] as? String,
              let to = edgeDict["to"] as? String,
              let weight = asDouble(edgeDict["weight"]) else {
            continue
        }
        if let existing = adjacency[from] {
            existing.append((to, weight))
        } else {
            adjacency[from] = [(to, weight)]
        }
        if let existing = adjacency[to] {
            existing.append((from, weight))
        } else {
            adjacency[to] = [(from, weight)]
        }
    }

    var dist: [String: Double] = [:]
    for node in adjacency.keys {
        dist[node] = Double.infinity
    }
    dist[source] = 0.0

    var heap = MinHeap()
    heap.push((0.0, source))
    var visited = Set<String>()

    while let item = heap.pop() {
        let currentDistance = item.0
        let node = item.1

        if visited.contains(node) {
            continue
        }
        guard let knownDistance = dist[node] else {
            continue
        }
        if currentDistance > knownDistance && currentDistance - knownDistance > 1e-12 {
            continue
        }

        visited.insert(node)

        if let neighbors = adjacency[node] {
            for (neighbor, weight) in neighbors {
                if visited.contains(neighbor) {
                    continue
                }
                let candidate = currentDistance + weight
                let oldDistance = dist[neighbor] ?? Double.infinity
                if candidate < oldDistance {
                    dist[neighbor] = candidate
                    heap.push((candidate, neighbor))
                }
            }
        }
    }

    let sortedNodes = Array(Set(nodes)).sorted()
    print("=== Shortest Paths from A ===")
    print()
    for node in sortedNodes {
        print("A -> \(node): \(formatDistance(dist[node] ?? Double.infinity))")
    }
}

