        }
    } else {
        format!("{}", d)
    }
}

fn print_u64(dist: &[u64], nodes: &[String], idx: &HashMap<&str, usize>) {
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted = nodes.clone();
    sorted.sort();

    for node in sorted {
        let d = idx
            .get(node.as_str())
            .copied()
            .map(|i| dist[i])
            .unwrap_or(u64::MAX);

        if d == u64::MAX {
            println!("A -> {}: Infinity", node);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}

fn print_f64(dist: &[f64], nodes: &[String], idx: &HashMap<&str, usize>) {
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted = nodes.clone();
    sorted.sort();

    for node in sorted {
        let d = idx
            .get(node.as_str())
            .copied()
            .map(|i| dist[i])
            .unwrap_or(f64::INFINITY);

        println!("A -> {}: {}", node, format_f64(d));
    }
}

fn get_field_str(fields: &[(String, Json)], key: &str) -> Option<&str> {
    fields.iter().find(|(k, _)| k == key).and_then(|(_, v)| {
        match v {
            Json::String(s) => Some(s),
            Json::Number(s) => Some(s.as_str()),
            _ => None,
        }
    })
}

fn main() {
    let input_path =
        "/tmp/…/graph.json";

    let input = fs::read_to_string(input_path).unwrap();
    let mut parser = Parser::new(&input);

    let root = parser.parse_value();
    parser.skip_ws();
    if parser.peek().is_some() {
        panic!("unexpected trailing input");
    }

    let fields = match root {
        Json::Object(f) => f,
        _ => panic!("root must be an object"),
    };

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<Json> = Vec::new();

    for (key, value) in fields {
        match key.as_str() {
            "nodes" => {
                if let Json::Array(arr) = value {
                    nodes = arr;
                }
            }
            "edges" => {
                if let Json::Array(arr) = value {
                    edges = arr;
                }
            }
            _ => {}
        }
    }

    let n = nodes.len();

    let mut idx: HashMap<&str, usize> = HashMap::new();
    for (i, node) in nodes.iter().enumerate() {
        idx.insert(node.as_str(), i);
    }

    let mut raw_edges: Vec<(usize, usize, String)> = Vec::new();
    let mut all_integer = true;

    for e in &edges {
        if let Json::Object(edge_fields) = e {
            if let (
                Some(from_s),
                Some(to_s),
                Some(weight_s),
            ) = (
                get_field_str(edge_fields, "from"),
                get_field_str(edge_fields, "to"),
                get_field_str(edge_fields, "weight"),
            ) {
                if let (Some(u), Some(v)) = (idx.get(from_s), idx.get(to_s)) {
                    raw_edges.push((u, v, weight_s.to_string()));

                    if parse_u64_weight(weight_s).is_none() {
                        all_integer = false;
                    }
                }
            }
        }
    }

    let src = *idx.get("A").unwrap_or(&0);

    if all_integer {
        let mut adj: Vec<Vec<(usize, u64)>> = vec![Vec::new(); n];

        for (u, v, w) in &raw_edges {
            if let Some(weight) = parse_u64_weight(w) {
                adj[u].push((v, weight));
                adj[v].push((u, weight));
            }
        }

        let dist = dijkstra_u64(&adj, src);
        print_u64(&dist, &nodes, &idx);
    } else {
        let mut adj: Vec<Vec<(usize, f64)>> = vec![Vec::new(); n];

        for (u, v, w) in &raw_edges {
            if let Ok(weight) = w.parse::<f64>() {
                if weight.is_finite() {
                    adj[u].push((v, weight));
                    adj[v].push((u, weight));
                }
            }
        }

        let dist = dijkstra_f64(&adj, src);
        print_f64(&dist, &nodes, &idx);
    }
}

import * as fs from "fs";
import * as path from "path";

const ROOT = "/tmp/…/project_tree";

interface FileInfo {
  rel: string;
  lines: number;
  chars: number;
}

function toPosix(p: string): string {
  return p.split(path.sep).join("/");
}

function countLines(buf: Buffer): number {
  const len = buf.length;
  if (len === 0) return 0;

  let lines = 0;
  for (let i = 0; i < len; i++) {
    if (buf[i] === 0x0a) {
      lines++;
    }
  }

  if (buf[len - 1] !== 0x0a) {
    lines++;
  }

  return lines;
}

async function walk(
  dir: string,
  visited: Set<string>,
  groups: Map<string, FileInfo[]>,
  totals: { files: number; lines: number; chars: number }
): Promise<void> {
  const absDir = path.resolve(dir);
  if (visited.has(absDir)) return;
  visited.add(absDir);

  let entries;
  try {
    entries = await fs.promises.readdir(dir, { withFileTypes: true });
  } catch (err) {
    return;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) {
      continue;
    }

    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      await walk(fullPath, visited, groups, totals);
    } else if (entry.isFile()) {
      const rel = toPosix(path.relative(ROOT, fullPath));
      const ext = path.extname(rel);
      const extension = ext === "" ? "." : ext;

      let buf;
      try {
        buf = await fs.promises.readFile(fullPath);
      } catch (err) {
        continue;
      }

      const info: FileInfo = {
        rel,
        lines: countLines(buf),
        chars: buf.length,
      };

      const files = groups.get(extension);
      if (files) {
        files.push(info);
      } else {
        groups.set(extension, [info]);
      }

      totals.files++;
      totals.lines += info.lines;
      totals.chars += info.chars;
    }
  }
}

async function main(): Promise<void> {
  const groups = new Map<string, FileInfo[]>();
  const totals = { files: 0, lines: 0, chars: 0 };
  const visited = new Set<string>();

  await walk(ROOT, visited, groups, totals);

  const extensions = Array.from(groups.keys()).sort();
  const output: string[] = [];

  output.push("=== File Tree Analysis ===");
  output.push("");

  for (const extension of extensions) {
    const files = groups.get(extension)!;
    files.sort((a, b) => (a.rel < b.rel ? -1 : a.rel > b.rel ? 1 : 0));

    let extLines = 0;
    let extChars = 0;
    for (const file of files) {
      extLines += file.lines;
      extChars += file.chars;
    }

    output.push(`Extension: ${extension}`);
    output.push(`  Files: ${files.length}`);
    output.push(`  Total Lines: ${extLines}`);
    output.push(`  Total Characters: ${extChars}`);

    for (const file of files) {
      output.push(`    ${file.rel}: ${file.lines} lines, ${file.chars} chars`);
    }
  }

  output.push("");
  output.push(`Total: ${totals.files} files, ${totals.lines} lines, ${totals.chars} characters`);

  process.stdout.write(output.join("\n") + "\n");
}

main().catch(() => {
  process.exitCode = 1;
});

import Foundation

let basePath = "/tmp/…/project_tree"
