struct FileInfo {
    let relativePath: String
    let lines: Int
    let characters: Int
}

var extensionsByGroup: [String: [FileInfo]] = [:]
var visitedDirectories = Set<String>()
var totalFiles = 0
var totalLines = 0
var totalCharacters = 0

func fileExtension(from path: String) -> String {
    let fileName = path.lastComponent ?? path
    guard let dotIndex = fileName.rIndex(of: "."), dotIndex > 0 else {
        return ""
    }
    return String(fileName[dotIndex...]).lowercased()
}

func relativePath(from fileURL: URL) -> String {
    guard let relative = fileURL.relative(to: baseURL) else {
        return fileURL.path
    }
    return relative.pathComponents
        .map { String($0) }
        .joined(separator: "/")
}

func countLinesAndCharacters(at url: URL) -> (lines: Int, characters: Int) {
    guard let handle = url.open(forReading) else {
        return (0, 0)
    }
    defer {
        handle.close()
    }

    var lines = 0
    var characters = 0
    var lastByte: UInt8 = 0
    let buffer = [UInt8](repeating: 0, count: 65536)

    while true {
        let bytesRead = handle.read(&buffer, maxByteCount: buffer.count)
        if bytesRead <= 0 {
            break
        }

        characters += bytesRead

        for index in 0..<bytesRead {
            let byte = buffer[index]
            if byte == UInt8(10) {
                lines += 1
            }
            lastByte = byte
        }
    }

    if characters > 0 && lastByte != UInt8(10) {
        lines += 1
    }

    return (lines, characters)
}

func walk(_ directoryURL: URL) {
    let directoryPath = directoryURL.path
    guard !visitedDirectories.contains(directoryPath) else {
        return
    }
    visitedDirectories.insert(directoryPath)

    guard let entries = try? FileManager.default.contentsOfDirectory(
        in: [directoryURL],
        options: [.skipSymbolicLinks]
    ) else {
        return
    }

    for entry in entries {
        guard let attributes = try? FileManager.default.attributes(
            ofFileAtPath: entry.path,
            in: .none
        ) else {
            continue
        }

        if attributes.contains(.isSymbolicLink) {
            continue
        }

        if attributes.contains(.isDirectory) {
            walk(entry)
        } else if attributes.contains(.isRegularFile) {
            let relative = relativePath(from: entry)
            let ext = fileExtension(from: entry.path)
            let (lines, characters) = countLinesAndCharacters(at: entry)

            extensionsByGroup[ext, default: []].append(
                FileInfo(relativePath: relative, lines: lines, characters: characters)
            )

            totalFiles += 1
            totalLines += lines
            totalCharacters += characters
        }
    }
}

