import java.io.IOException;
import java.io.InputStream;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

public class Main {
    private static final Path ROOT = Paths.get("/tmp/…/project_tree");

    private static class FileStat {
        String path;
        long lines;
        long chars;

        FileStat(String path, long lines, long chars) {
            this.path = path;
            this.lines = lines;
            this.chars = chars;
        }
    }

    private static class Group {
        String extension;
        List<FileStat> files;
        long fileCount;
        long totalLines;
        long totalChars;

        Group() {
            files = new ArrayList<FileStat>();
        }

        void add(FileStat stat) {
            files.add(stat);
            fileCount++;
            totalLines += stat.lines;
            totalChars += stat.chars;
        }
    }

    public static void main(String[] args) {
        Map<String, Group> groups = new TreeMap<String, Group>();

        try {
            if (Files.isDirectoryNoSymlinks(ROOT)) {
                Set<Path> visited = new HashSet<Path>();
                walk(ROOT, "", groups, visited);
            }
        } catch (IOException e) {
            // If the root directory cannot be processed, output zero totals.
        }

        for (Group group : groups.values()) {
            Collections.sort(group.files, new Comparator<FileStat>() {
                @Override
                public int compare(FileStat a, FileStat b) {
                    return a.path.compareTo(b.path);
                }
            });
        }

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        StringBuilder out = new StringBuilder();
        out.append("=== File Tree Analysis ===\n\n");

        boolean hasGroups = false;

        for (Group group : groups.values()) {
            hasGroups = true;
            totalFiles += group.fileCount;
            totalLines += group.totalLines;
            totalChars += group.totalChars;

            if (group.extension.isEmpty()) {
                out.append("Extension:\n");
            } else {
                out.append("Extension: ").append(group.extension).append('\n');
            }

            out.append("  Files: ").append(group.fileCount).append('\n');
            out.append("  Total Lines: ").append(group.totalLines).append('\n');
            out.append("  Total Characters: ").append(group.totalChars).append('\n');

            for (FileStat stat : group.files) {
                out.append("    ")
                   .append(stat.path)
                   .append(": ")
                   .append(stat.lines)
                   .append(" lines, ")
                   .append(stat.chars)
                   .append(" chars\n");
            }
        }

        if (!hasGroups) {
            out.append("Total: 0 files, 0 lines, 0 characters\n");
        } else {
            out.append('\n');
            out.append("Total: ")
                .append(totalFiles)
                .append(" files, ")
                .append(totalLines)
                .append(" lines, ")
                .append(totalChars)
                .append(" characters\n");
        }

        System.out.print(out.toString());
    }

    private static void walk(Path dir, String relDir, Map<String, Group> groups, Set<Path> visited) throws IOException {
        Path absoluteDir = dir.toAbsolutePath().normalize();
        if (!visited.add(absoluteDir)) {
            return;
        }

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            for (Path entry : stream) {
                if (Files.isSymbolicLink(entry)) {
                    continue;
                }

                Path fileNamePath = entry.getFileName();
                if (fileNamePath == null) {
                    continue;
                }

                String fileName = fileNamePath.toString();
                String childRel = relDir.isEmpty() ? fileName : relDir + "/" + fileName;

                if (Files.isDirectoryNoSymlinks(entry)) {
                    walk(entry, childRel, groups, visited);
                } else if (Files.isRegularFileNoSymlinks(entry)) {
                    processFile(entry, childRel, fileName, groups);
                }
            }
        } catch (IOException e) {
            // Skip directories that cannot be listed.
        }
    }

    private static void processFile(Path path, String relPath, String fileName, Map<String, Group> groups) {
        long lines;
        long chars;

        try {
            long[] stats = countLinesAndBytes(path);
            lines = stats[0];
            chars = stats[1];
        } catch (IOException e) {
            lines = 0;
            chars = 0;
        }

        String extension = extensionOf(fileName);
        Group group = groups.get(extension);
        if (group == null) {
            group = new Group();
            group.extension = extension;
            groups.put(extension, group);
        }

        group.add(new FileStat(relPath, lines, chars));
    }

    private static long[] countLinesAndBytes(Path path) throws IOException {
        long bytes = 0;
        long newlines = 0;
        boolean lastWasNewline = true;

        try (InputStream in = Files.newInputStream(path)) {
            byte[] buffer = new byte[8192];
            int read;

            while ((read = in.read(buffer)) != -1) {
                bytes += read;
                for (int i = 0; i < read; i++) {
                    if (buffer[i] == '\n') {
                        newlines++;
                        lastWasNewline = true;
                    } else {
                        lastWasNewline = false;
                    }
                }
            }
        }

        long lines = newlines;
        if (bytes > 0 && !lastWasNewline) {
            lines++;
        }

        return new long[]{lines, bytes};
    }

    private static String extensionOf(String fileName) {
        int dot = fileName.lastIndexOf('.');
        if (dot <= 0) {
            return "";
        }
        return fileName.substring(dot);
    }
}

