            out.append("  Files: ").append(group.fileCount).append('\n');
            out.append("  Total Lines: ").append(group.totalLines).append('\n');
            out.append("  Total Characters: ").append(group.totalChars).append('\n');

            for (FileStat stat : group.files) {
                out.append("    ")
                   .append(stat.path)
                   .append(": ")
                   .append(stat.lines)
                   .append(" lines, ")
                   .append(stat.chars)
                   .append(" chars\n");
            }
        }

        if (!hasGroups) {
            out.append("Total: ")
                .append(totalFiles)
                .append(" files, ")
                .append(totalLines)
                .append(" lines, ")
                .append(totalChars)
                .append(" characters\n");
        } else {
            out.append('\n');
            out.append("Total: ")
                .append(totalFiles)
                .append(" files, ")
                .append(totalLines)
                .append(" lines, ")
                .append(totalChars)
                .append(" characters\n");
        }

        System.out.print(out.toString());
    }

    private static void walk(Path dir, String relDir, Map<String, Group> groups, Set<Path> visited) throws IOException {
        Path absoluteDir = dir.toAbsolutePath().normalize();
        if (!visited.add(absoluteDir)) {
            return;
        }

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            for (Path entry : stream) {
                if (Files.isSymlink(entry)) {
                    continue;
                }

                Path fileNamePath = entry.getFileName();
                if (fileNamePath == null) {
                    continue;
                }

                String fileName = fileNamePath.toString();
                String childRel = relDir.isEmpty() ? fileName : relDir + "/" + fileName;

                if (Files.isDirectory(entry)) {
                    walk(entry, childRel, groups, visited);
                } else if (Files.isRegularFile(entry)) {
                    processFile(entry, childRel, fileName, groups);
                }
            }
        } catch (IOException e) {
            // Skip directories that cannot be listed.
        }
    }

    private static void processFile(Path path, String relPath, String fileName, Map<String, Group> groups) {
        long lines;
        long chars;

        try {
            long[] stats = countLinesAndBytes(path);
            lines = stats[0];
            chars = stats[1];
        } catch (IOException e) {
            lines = 0;
            chars = 0;
        }

        String extension = extensionOf(fileName);
        Group group = groups.get(extension);
        if (group == null) {
            group = new Group();
            group.extension = extension;
            groups.put(extension, group);
        }

        group.add(new FileStat(relPath, lines, chars));
    }

    private static long[] countLinesAndBytes(Path path) throws IOException {
        long bytes = 0;
        long newlines = 0;
        boolean lastWasNewline = true;

        try (InputStream in = Files.newInputStream(path)) {
            byte[] buffer = new byte[8192];
            int read;

            while ((read = in.read(buffer)) != -1) {
                bytes += read;
                for (int i = 0; i < read; i++) {
                    if (buffer[i] == '\n') {
                        newlines++;
                        lastWasNewline = true;
                    } else {
                        lastWasNewline = false;
                    }
                }
            }
        }

        long lines = newlines;
        if (bytes > 0 && !lastWasNewline) {
            lines++;
        }

        return new long[]{lines, bytes};
    }

    private static String extensionOf(String fileName) {
        int dot = fileName.lastIndexOf('.');
        if (dot <= 0) {
            return "";
        }
        return fileName.substring(dot);
    }
}

