import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        String hostname = runCommand("hostname");
        String os = runCommand("uname", "-s");
        String architecture = runCommand("uname", "-m");
        String username = runCommand("whoami");

        StringBuilder json = new StringBuilder();
        json.append("{\n");
        json.append("  \"hostname\": \"").append(escapeJson(hostname)).append("\",\n");
        json.append("  \"os\": \"").append(escapeJson(os)).append("\",\n");
        json.append("  \"architecture\": \"").append(escapeJson(architecture)).append("\",\n");
        json.append("  \"username\": \"").append(escapeJson(username));
        json.append("\n");
        json.append("}");

        System.out.print(json.toString());
    }

    private static String runCommand(String... command) {
        try {
            Process process = new ProcessBuilder(command)
                    .redirectErrorStream(false)
                    .start();

            StringBuilder output = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append('\n');
                }
            }

            process.waitFor();
            return output.toString().trim();
        } catch (Exception e) {
            return "";
        }
    }

    private static String escapeJson(String value) {
        if (value == null) {
            return "";
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\b':
                    sb.append("\\b");
                    break;
                case '\f':
                    sb.append("\\f");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }
}

