use std::collections::{BTreeMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

struct FileStat {
    path: String,
    lines: usize,
    chars: usize,
}

struct Totals {
    files: usize,
    lines: usize,
    chars: usize,
}

fn walk(
    dir: &Path,
    rel: &Path,
    visited: &mut HashSet<PathBuf>,
    groups: &mut BTreeMap<String, Vec<FileStat>>,
    totals: &mut Totals,
) {
    if !visited.insert(dir.to_path_buf()) {
        return;
    }

    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let file_type = match entry.file_type() {
            Ok(file_type) => file_type,
            Err(_) => continue,
        };

        if file_type.is_symlink() {
            continue;
        }

        let child_rel = rel.join(entry.file_name());
        let child_path = entry.path();

        if file_type.is_dir() {
            walk(&child_path, &child_rel, visited, groups, totals);
        } else if file_type.is_file() {
            process_file(&child_path, &child_rel, groups, totals);
        }
    }
}

fn process_file(
    path: &Path,
    rel: &Path,
    groups: &mut BTreeMap<String, Vec<FileStat>>,
    totals: &mut Totals,
) {
    let bytes = match fs::read(path) {
        Ok(bytes) => bytes,
        Err(_) => return,
    };

    let chars = bytes.len();

    let mut lines = bytes.iter().filter(|&&b| b == b'\n').count();
    if let Some(&last) = bytes.last() {
        if last != b'\n' {
            lines += 1;
        }
    }

    let ext = extension_of(path);
    groups
        .entry(ext)
        .or_insert_with(Vec::new)
        .push(FileStat {
            path: path_display(rel),
            lines,
            chars,
        });

    totals.files += 1;
    totals.lines += lines;
    totals.chars += chars;
}

fn extension_of(path: &Path) -> String {
    let ext = path
        .extension()
        .and_then(|ext| {
            if ext.as_os_str().is_empty() {
                None
            } else {
                Some(ext)
            }
        });

    ext.map(|ext| format!(".{}", ext.to_string_lossy())).unwrap_or_default()
}

fn path_display(path: &Path) -> String {
    let mut display = String::new();
    for (i, component) in path.components().enumerate() {
        if i > 0 {
            display.push('/');
        }
        display.push_str(&component.as_os_str().to_string_lossy());
    }
    display
}

fn print_report(groups: &BTreeMap<String, Vec<FileStat>>, totals: &Totals) {
    println!("=== File Tree Analysis ===");
    println!();

    if !groups.is_empty() {
        for (ext, files) in groups.iter() {
            if ext.is_empty() {
                println!("Extension:");
            } else {
                println!("Extension: {}", ext);
            }

            println!("  Files: {}", files.len());

            let group_lines: usize = files.iter().map(|file| file.lines).sum();
            let group_chars: usize = files.iter().map(|file| file.chars).sum();

            println!("  Total Lines: {}", group_lines);
            println!("  Total Characters: {}", group_chars);

            for file in files {
                println!(
                    "    {}: {} lines, {} chars",
                    file.path, file.lines, file.chars
                );
            }
        }

        println!();
    }

    println!(
        "Total: {} files, {} lines, {} characters",
        totals.files, totals.lines, totals.chars
    );
}

fn main() {
    let root = PathBuf::from(
        "/tmp/…/project_tree",
    );

    let mut groups: BTreeMap<String, Vec<FileStat>> = BTreeMap::new();
    let mut totals = Totals {
        files: 0,
        lines: 0,
        chars: 0,
    };
    let mut visited = HashSet::new();

    walk(&root, Path::new(), &mut visited, &mut groups, &mut totals);

    for files in groups.values_mut() {
        files.sort_by(|a, b| a.path.cmp(&b.path));
    }

    print_report(&groups, &totals);
}

