import Foundation

func stripTrailingWhitespace(_ text: String) -> String {
    var result = text
    while let last = result.suffix(1) {
        if last.isWhitespace || last == "\n" || last == "\r" || last == "\t" {
            result.removeLast()
        } else {
            break
        }
    }
    return result
}

func runCommand(_ command: String) -> String {
    let process = Process()
    process.executablePath = "/bin/sh"
    process.arguments = ["-c", command]
    process.stdinClosed = true
    process.stdoutPipe = true
    process.stderrPipe = true

    guard let output = try? process.output,
          let text = String(data: output, encoding: .utf8) else {
        return ""
    }

    return stripTrailingWhitespace(text)
}

func jsonEscape(_ value: String) -> String {
    var escaped = ""
    for scalar in value.unicodeScalars {
        switch scalar {
        case "\"" :
            escaped += "\\\""
        case "\\" :
            escaped += "\\\\"
        case "\n" :
            escaped += "\\n"
        case "\r" :
            escaped += "\\r"
        case "\t" :
            escaped += "\\t"
        case "\b" :
            escaped += "\\b"
        case "\f" :
            escaped += "\\f"
        case Unicode.Scalar.controls:
            escaped += "\\u\(String(format: "%04x", scalar as Int))"
        default:
            escaped += String(scalar)
        }
    }
    return escaped
}

