static void strip_trailing_whitespace(char *s)
{
    if (s == NULL) {
        return;
    }

    size_t length = strlen(s);
    while (length > 0 && isspace((unsigned char)s[length - 1])) {
        length--;
    }
    s[length] = '\0';
}

