    }

    size_t capacity = 256;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (buffer == NULL) {
        pclose(pipe);
        return NULL;
    }

    int ch;
    while ((ch = fgetc(pipe)) != EOF) {
        if (length + 1 >= capacity) {
            if (capacity > (size_t)-1 / 2) {
                capacity = (size_t)-1;
            } else {
                capacity *= 2;
            }

            char *new_buffer = realloc(buffer, capacity);
            if (new_buffer == NULL) {
                free(buffer);
                pclose(pipe);
                return NULL;
            }
            buffer = new_buffer;
        }

        buffer[length++] = (char)ch;
    }

    buffer[length] = '\0';
    pclose(pipe);
    strip_trailing_whitespace(buffer);
    return buffer;
}

static char *json_escape_string(const char *s)
{
    if (s == NULL) {
        s = "";
    }

    size_t input_length = strlen(s);
    size_t capacity = input_length * 6 + 3;
    char *out = malloc(capacity);
    if (out == NULL) {
        return NULL;
    }

    size_t j = 0;
    out[j++] = '"';

    static const char hex[] = "0123456789ABCDEF";
    const unsigned char *p;
    unsigned char c;

    p = (const unsigned char *)s;
    while (*p != '\0') {
        c = *p;
        if (c == '"') {
            out[j++] = '\\';
            out[j++] = '"';
        } else if (c == '\\') {
            out[j++] = '\\';
            out[j++] = '\\';
        } else if (c < 0x20) {
            out[j++] = '\\';
            out[j++] = 'u';
            out[j++] = '0';
            out[j++] = '0';
            out[j++] = hex[c >> 4];
            out[j++] = hex[c & 0x0F];
        } else {
            out[j++] = (char)c;
        }
        ++p;
    }

    out[j++] = '"';
    return out;
}

