static void free_entry(FileEntry *entry) {
    free(entry->rel);
    free(entry->ext);
    free(entry);
}

static void free_array(EntryArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free_entry(&array->data[i]);
    }
    free(array->data);
    array->data = NULL;
    array->count = 0;
