static char *duplicate_string(const char *s) {
    size_t n = s ? strlen(s) : 0;
    char *p = malloc(n + 1);
    if (!p) return NULL;
    if (s) strcpy(p, s);
    else p[0] = '\0';
    return p;
}

static char *join_path(const char *base, const char *name) {
    size_t base_len = strlen(base);
    size_t name_len = strlen(name);
    size_t total = base_len + name_len + 2;
    char *result = malloc(total);
    if (!result) return NULL;

    if (base_len == 0) {
        strcpy(result, name);
    } else if (base[base_len - 1] == '/') {
        snprintf(result, total, "%s%s", base, name);
    } else {
        snprintf(result, total, "%s/%s", base, name);
    }
    return result;
}

static char *join_rel(const char *base, const char *name) {
    if (base[0] == '\0') {
        return duplicate_string(name);
    }

    size_t total = strlen(base) + strlen(name) + 2;
    char *result = malloc(total);
    if (!result) return NULL;

    snprintf(result, total, "%s/%s", base, name);
    return result;
}

static char *extension_of(const char *name) {
    const char *dot = strrchr(name, '.');
    if (dot == NULL || dot == name) {
        return duplicate_string("");
    }
    return duplicate_string(dot);
}

static int add_entry(EntryArray *array, const char *rel, const char *ext,
                     uint64_t lines, uint64_t chars) {
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 16;
        FileEntry *tmp = realloc(array->data, new_capacity * sizeof(*tmp));
        if (!tmp) return 0;
        array->data = tmp;
        array->capacity = new_capacity;
    }

    FileEntry *item = &array->data[array->count];
    item->rel = duplicate_string(rel);
    item->ext = duplicate_string(ext);

    if (!item->rel || !item->ext) {
        free(item->rel);
        free(item->ext);
        return 0;
    }

    item->lines = lines;
    item->chars = chars;
    array->count++;
    return 1;
}

static void count_file(const char *path, uint64_t *lines, uint64_t *chars) {
    FILE *fp = fopen(path, "rb");
    if (!fp) {
        *lines = 0;
        *chars = 0;
        return;
    }

    size_t buf_size = 64 * 1024;
    char *buf = malloc(buf_size);
    if (!buf) {
        fclose(fp);
        *lines = 0;
        *chars = 0;
        return;
    }

    uint64_t total_chars = 0;
    uint64_t newline_count = 0;
    int last_byte = 0;

    for (;;) {
        size_t n = fread(buf, 1, buf_size, fp);
        if (n == 0) break;

        for (size_t i = 0; i < n; ++i) {
            ++total_chars;
            last_byte = buf[i];
            if (buf[i] == '\n') {
                ++newline_count;
            }
        }
    }

    free(buf);
    fclose(fp);

    uint64_t line_count = newline_count;
    if (total_chars > 0 && last_byte != '\n') {
        ++line_count;
    }

    *lines = line_count;
    *chars = total_chars;
}

static void walk_directory(const char *full_path, const char *rel_path,
                           EntryArray *entries) {
    DIR *dir = opendir(full_path);
    if (!dir) return;

    struct dirent *de;
    while ((de = readdir(dir)) != NULL) {
        const char *name = de->d_name;

        if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0) {
            continue;
        }

        char *child_full = join_path(full_path, name);
        if (!child_full) continue;

        char *child_rel = join_rel(rel_path, name);
        if (!child_rel) {
            free(child_full);
            continue;
        }

        struct stat st;
        if (lstat(child_full, &st) != 0) {
            free(child_full);
            free(child_rel);
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            walk_directory(child_full, child_rel, entries);
        } else if (S_ISREG(st.st_mode)) {
            uint64_t lines = 0;
            uint64_t chars = 0;
            count_file(child_full, &lines, &chars);

            char *ext = extension_of(name);
            if (ext) {
                add_entry(entries, child_rel, ext, lines, chars);
            }
            free(ext);
        }

        free(child_full);
        free(child_rel);
    }

    closedir(dir);
}

