        System.out.print(output);
    }

    private static int[][] multiply(int[][] a, int[][] b) {
        int rows = a.length;
        int cols = b[0].length;
        int[][] result = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int sum = 0;
                for (int k = 0; k < b.length; k++) {
                    sum += a[i][k] * b[k][j];
                }
                result[i][j] = sum;
            }
        }

        return result;
    }

    private static long determinant(int[][] matrix) {
        long a = matrix[0][0];
        long b = matrix[0][1];
        long c = matrix[0][2];

        long d = matrix[1][0];
        long e = matrix[1][1];
        long f = matrix[1][2];

        long g = matrix[2][0];
        long h = matrix[2][1];
        long i = matrix[2][2];

        return a * (e * i - f * h)
             - b * (d * i - f * g)
             + c * (d * h - e * g);
    }

    private static void printMatrix(StringBuilder output, int[][] matrix) {
        for (int i = 0; i < matrix.length; i++) {
            output.append("  ");

            for (int j = 0; j < matrix[i].length; j++) {
                if (j > 0) {
                    output.append(' ');
                }

                output.append(padRight(matrix[i][j]));
            }

            output.append('\n');
        }
    }

    private static String padRight(int value) {
        String text = Integer.toString(value);
        int spaces = 4 - text.length();

        if (spaces > 0) {
            StringBuilder padded = new StringBuilder();
            for (int i = 0; i < spaces; i++) {
                padded.append(' ');
            }
            padded.append(text);
            return padded.toString();
        }

        return text;
    }
}

