function multiply(a: number[][], b: number[][]): number[][] {
  const result: number[][] = [];

  for (let i = 0; i < a.length; i++) {
    const currentRow: number[] = [];

    for (let j = 0; j < b[0].length; j++) {
      let total = 0;

      for (let k = 0; k < a[i].length; k++) {
        total += a[i][k] * b[k][j];
      }

      currentRow.push(total);
    }

    result.push(currentRow);
  }

  return result;
}

function determinant(m: number[][]): number {
  const a = m[0][0];
  const b = m[0][1];
  const c = m[0][2];

  const d = m[1][0];
  const e = m[1][1];
  const f = m[1][2];

  const g = m[2][0];
  const h = m[2][1];
  const i = m[2][2];

  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

function formatValue(value: number, width: number): string {
  const text = value.toString();
  let prefix = "";

  while (prefix.length + text.length < width) {
    prefix += " ";
  }

  return prefix + text;
}

function formatRow(row: number[]): string {
  return "  " + row.map((value) => formatValue(value, 4)).join(" ");
}

