fn multiply(a: &[Vec<i32>], b: &[Vec<i32>]) -> Vec<Vec<i32>> {
    let n = a.len();
    let m = b[0].len();
    let p = b.len();

    let mut c = vec![vec![0; m]; n];

    for i in 0..n {
        for j in 0..m {
            let mut sum = 0;
            for k in 0..p {
                sum += a[i][k] * b[k][j];
            }
            c[i][j] = sum;
        }
    }

    c
}

fn determinant(m: &[Vec<i32>]) -> i32 {
    let (a, b, c) = (m[0][0], m[0][1], m[0][2]);
    let (d, e, f) = (m[1][0], m[1][1], m[1][2]);
    let (g, h, i) = (m[2][0], m[2][1], m[2][2]);

    a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

