static long long determinant3(const int *m)
{
    long long m0 = m[0];
    long long m1 = m[1];
    long long m2 = m[2];
    long long m3 = m[3];
    long long m4 = m[4];
    long long m5 = m[5];
    long long m6 = m[6];
    long long m7 = m[7];
    long long m8 = m[8];

    return m0 * (m4 * m8 - m5 * m7)
         - m1 * (m3 * m8 - m5 * m6)
         + m2 * (m3 * m7 - m4 * m6);
}

